+                        kind: "joint",
+                        row,
+                        constant,
+                    }),
+                    None => {
+                        return Err("degenerate-leg");
+                    }
+                }
+            }
+            joint_checks.push(JointCheck {
+                j,
+                iv,
+                ov,
+                constrained,
+                smooth: occ.smooth,
+            });
+        }
+    }
+    Ok(joint_checks)
+}
