        self.visible
            .get_or_init(|| geometry::split_visible(self.parsed().expect("validated source"), true))
    }
    fn pairs(&self) -> &(Vec<geometry::Pair>, Vec<geometry::Skipped>) {
        self.pairs.get_or_init(|| {
