        assert_eq!(a.iter().flatten().filter(|v| **v != 0.0).count(), 4384);
        assert_eq!(g.iter().flatten().filter(|v| **v != 0.0).count(), 81);
        assert_eq!(
            a.iter()
                .filter(|row| row.iter().any(|v| v.to_bits() == (-0.0f64).to_bits()))
                .count(),
            722
