    let target = match decide_parity_target(axis_src, predicted, rel_med, &prepped) {
        Ok(target) => target,
        Err(reason) => {
            return Ok(abstain(
                original_upstream,
                reason,
                serde_json::json!({"skipped": skipped_json}),
