            "axis-uncontained",
            serde_json::json!({
                "skipped": skipped_json,
                "locus": {"cmin": locus.cmin, "cmax": locus.cmax,
                          "n": locus.n, "skipped_slabs": locus.skipped},
            }),
        ));
    }
    let Some(waist) = selected_waist.or_else(|| waist_from_slabs(&parsed)) else {
        return Ok(abstain(
            original_upstream,
            "no-waist",
            serde_json::json!({"skipped": skipped_json}),
        ));
    };
    let rel_med = median(
        &reference
            .anchors
            .iter()
            .map(|a| a.rel)
            .collect::<Vec<f64>>(),
    );
    let predicted = waist.width * (1.0 + rel_med);
    let axis_src = locus.mid();
    let target = match decide_parity_target(axis_src, predicted, rel_med, &prepped) {
        Ok(target) => target,
        Err(reason) => {
            return Ok(abstain(
                original_upstream,
                reason,
                serde_json::json!({"skipped": skipped_json}),
            ));
        }
    };
    let f_k = 2.0 * target;
    let mut sides = Vec::new();
    for info in &prepped {
        for side in [&info.a, &info.b] {
            sides.push(Side {
                pair: info.id.clone(),
                p0: side.p0,
                p1: side.p1,
                i0: side.i0,
                i1: side.i1,
                t0: side.t0,
                t1: side.t1,
            });
        }
    }
    let matches = match_borders(&sides, axis_src, EPS_PARITY);
    if matches.is_empty() {
        return Ok(abstain(
            original_upstream,
            "no-symmetry-matches",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    let (system, fixed, var_verts) = assemble(
        &parsed,
        &fitted_coords,
        &mut prepped,
        &reference.anchors,
        size_px,
        &pins,
        &owned,
"}

item.stdout:
    );
    let symmetry = symmetry_rows(&system, &matches, axis_src, f_k, size_px);
    // The distortion and relative-width rows remain soft; symmetry rows
    // alone constrain the parity phase (prototype `group != symmetry`).
    let width_rows: Vec<(&Vec<f64>, f64)> = system
        .rows
        .iter()
        .map(|(_, row, constant)| (row, *constant))
        .collect();
    let base = parsed.oncurve.clone();
    let upstream = fitted_coords.clone();
    let gaps: Vec<f64> = upstream
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let mut columns: Vec<usize> = var_verts
        .iter()
        .filter(|v| !fixed.contains_key(&(**v, 0)))
        .map(|v| 2 * *v)
        .collect();
    columns.sort();
    if columns.is_empty() {
        return Ok(abstain(
            original_upstream,
            "no-horizontal-freedom",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    let project = |row: &[f64], constant: f64| -> (Vec<f64>, f64) {
        (
            columns.iter().map(|c| row[*c]).collect(),
            -dot(row, &gaps) - constant,
        )
    };
    let a_mat: Vec<Vec<f64>> = width_rows.iter().map(|(r, c)| project(r, *c).0).collect();
    let b_vec: Vec<f64> = width_rows.iter().map(|(r, c)| project(r, *c).1).collect();
    let g_mat: Vec<Vec<f64>> = symmetry.iter().map(|(r, c)| project(r, *c).0).collect();
    let h_vec: Vec<f64> = symmetry.iter().map(|(r, c)| project(r, *c).1).collect();
    let bounds: Vec<f64> = columns
        .iter()
        .map(|col| {
            let v = col / 2;
            prepped
                .iter()
                .filter(|info| [info.a.i0, info.a.i1, info.b.i0, info.b.i1].contains(&v))
                .map(|info| info.bound)
                .fold(f64::INFINITY, f64::min)
        })
        .collect();
    let Some((delta, qp_info)) = qp::bounded_equalities(&a_mat, &b_vec, &g_mat, &h_vec, &bounds)
    else {
        return Ok(abstain(
            original_upstream,
            "phase-bounds-incompatible",
            serde_json::json!({"skipped": skipped_json}),
        ));
    };
    let mut flat_delta = vec![0.0; gaps.len()];
    for (k, col) in columns.iter().enumerate() {
        flat_delta[*col] = delta[k];
    }
    let mut peaks: HashMap<String, f64> = HashMap::new();
    for info in &prepped {
        let peak = [info.a.i0, info.a.i1, info.b.i0, info.b.i1]
            .iter()
            .map(|v| flat_delta[2 * *v].hypot(flat_delta[2 * *v + 1]))
            .fold(0.0, f64::max);
        peaks.insert(info.id.clone(), peak);
    }
    let over: Vec<&super::PreppedInfo> = prepped
        .iter()
        .filter(|info| peaks[&info.id] > info.bound)
        .collect();
    if !over.is_empty()
        && over
            .iter()
            .map(|info| peaks[&info.id] - info.bound)
            .fold(0.0, f64::max)
            > 1e-9
    {
        return Ok(abstain(
            original_upstream,
            "movement-budget",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    for info in prepped.iter_mut() {
        info.peak = peaks[&info.id];
    }
    let table = geometry::index_map(original_upstream);
    let mut candidate = original_upstream.to_vec();
    let flat_up: Vec<f64> = upstream.iter().flat_map(|p| [p[0], p[1]]).collect();
    let flat_cand: Vec<f64> = flat_up
        .iter()
        .zip(flat_delta.iter())
        .map(|(u, d)| u + d)
        .collect();
    let mut sorted_verts: Vec<usize> = var_verts.iter().copied().collect();
    sorted_verts.sort();
    for v in sorted_verts {
        let Some(pos) = table.get(v).copied().flatten() else {
            continue;
        };
        for axis in 0..2 {
            if fixed.contains_key(&(v, axis)) {
                continue;
            }
            let value = flat_cand[2 * v + axis];
            if value == flat_up[2 * v + axis] {
                continue;
            }
            let rounded = geometry::round_26_6(value) as f32;
            match &mut candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                }
                FittedCommand::QuadTo(x1, y1, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1);
                }
                FittedCommand::CurveTo(x1, y1, x2, y2, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1, x2, y2);
                }
                FittedCommand::Close => {}
            }
        }
    }
    if candidate == original_upstream {
        return Ok(abstain(
            original_upstream,
            "no-movement",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    let mut validity = validate(
        &parsed,
        &fitted,
        original_upstream,
        &candidate,
        &portions,
        &mut prepped,
        &pins,
        &owned,
        source,
    );
    if validity.ok {
        if let Err(reason) = geometry::curve_sweep_ok(
            &parsed,
            &fitted_coords,
            &candidate,
            &geometry::curve_controls(&fitted),
        ) {
            validity.ok = false;
            validity.stage = reason.to_string();
        }
    }
    // Exact f32-bits pins: coordinate equality also holds across signed
    // zero, but bit identity is the upstream contract here.
    if validity.ok {
        let cand_table = geometry::index_map(&candidate);
        let mut inverted: HashMap<usize, usize> = HashMap::new();
        for (idx, pos) in cand_table.iter().enumerate() {
            if let Some(p) = pos {
                inverted.insert(*p, idx);
            }
        }
        let mut bits_ok = true;
        for (pos, cmd) in candidate.iter().enumerate() {
            let Some(&idx) = inverted.get(&pos) else {
                continue;
            };
            for axis in owned.iter().copied() {
                if bits_of(cmd, axis) != bits_of(&original_upstream[pos], axis) {
                    let _ = idx;
                    bits_ok = false;
                }
            }
        }
        for pin in pins.iter() {
            let Some(pos) = cand_table.get(*pin).copied().flatten() else {
                continue;
            };
            for axis in 0..2 {
                if bits_of(&candidate[pos], axis) != bits_of(&original_upstream[pos], axis) {
                    bits_ok = false;
                }
            }
        }
        if !bits_ok {
            validity.ok = false;
            validity.stage = "pins-bits-changed".to_string();
        }
    }
    let match_cost = |flat: &[f64]| -> f64 {
        width_rows
            .iter()
            .map(|(row, constant)| (dot(row, flat) + constant).powi(2))
            .sum()
    };
    let sym_cost = |flat: &[f64]| -> f64 {
        symmetry
            .iter()
            .map(|(row, constant)| (dot(row, flat) + constant).powi(2))
            .sum()
    };
    let flat_base_up: Vec<f64> = upstream
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let cost_upstream = match_cost(&flat_base_up);
    let sym_upstream = sym_cost(&flat_base_up);
    let parsed_cand = geometry::parse_commands(&candidate);
    let (cost_candidate, sym_candidate) = match parsed_cand {
        Ok(cand) => {
            let flat: Vec<f64> = cand
                .oncurve
                .iter()
                .zip(base.iter())
                .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
                .collect();
            (Some(match_cost(&flat)), Some(sym_cost(&flat)))
        }
        Err(()) => (None, None),
    };
    let cost_ok = cost_candidate.is_some_and(|c| c < cost_upstream);
    let symmetry_ok = sym_candidate.is_some_and(|c| c < sym_upstream);
    validity.cost_upstream = Some(cost_upstream);
    validity.cost_candidate = cost_candidate;
    validity.cost_ok = cost_ok;
    if !cost_ok {
        validity.ok = false;
        validity.stage = "no-cost-decrease".to_string();
    } else if !symmetry_ok {
        validity.ok = false;
        validity.stage = "no-symmetry-decrease".to_string();
    }
    let achieved = achieved_widths(&prepped, &candidate);
    let widths = mean_widths(&achieved);
    let diagnostics = serde_json::json!({
        "epsilon": EPS_PARITY,
        "axis_src": axis_src,
        "qp": {"iterations": qp_info.iterations, "equality_error": qp_info.equality_error,
                "stationarity_error": qp_info.stationarity_error, "active": qp_info.active},
        "locus": {"cmin": locus.cmin, "cmax": locus.cmax,
                  "n": locus.n, "skipped_slabs": locus.skipped},
        "waist": {"width": waist.width, "mid": waist.mid, "level": waist.level,
                  "predicted": predicted, "rel_med": rel_med},
        "parity_target": target,
        "f_k": f_k,
        "matches": matches.len(),
        "symmetry_upstream": sym_upstream,
        "symmetry_candidate": sym_candidate,
        "symmetry_ok": symmetry_ok,
    });
    if !validity.ok {
        let fallback = achieved_widths(&prepped, original_upstream);
        return Ok(FitResult {
            commands: original_upstream.to_vec(),
            applied: false,
            reason: "invalid-candidate".to_string(),
            diagnostics: serde_json::json!({
                "validity": super::validity_json(&validity),
                "pairs": achieved_json(&prepped, &achieved),
                "skipped": skipped_json,
                "diagnostics": diagnostics,
                "movement": peaks.values().cloned().fold(0.0, f64::max),
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "widths": mean_widths(&fallback),
                "reference": reference_meta(reference),
            }),
        });
    }
    Ok(FitResult {
        commands: candidate,
        applied: true,
        reason: "applied-joint".to_string(),
        diagnostics: serde_json::json!({
            "validity": super::validity_json(&validity),
            "pairs": achieved_json(&prepped, &achieved),
            "skipped": skipped_json,
            "diagnostics": diagnostics,
            "movement": peaks.values().cloned().fold(0.0, f64::max),
            "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
            "size_px": size_px,
            "widths": widths,
            "reference": reference_meta(reference),
        }),
    })
}

impl AxisLocus {
    fn mid(&self) -> f64 {
        (self.cmin + self.cmax) / 2.0
    }
}

#[cfg(test)]
mod correspondence_tests {
    use super::*;

    fn vside(pair: &str, x: f64, indices: [usize; 2], interval: [f64; 2]) -> Side {
        Side {
            pair: pair.into(),
            p0: [x, 0.0],
            p1: [x, 1.0],
            i0: indices[0],
            i1: indices[1],
            t0: interval[0],
            t1: interval[1],
        }
    }

    #[test]
    fn forward_match_orders_sides_and_keeps_metadata() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.0, [2, 3], [0.125, 0.625]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        let (first, second, dist) = &matches[0];
        assert_eq!(first.pair, "a");
        assert_eq!(second.pair, "b");
        assert_eq!(dist, &0.0);
        assert_eq!(second.p0, [1.0, 0.0]);
        assert_eq!(second.p1, [1.0, 1.0]);
        assert_eq!((second.i0, second.i1), (2, 3));
        assert_eq!((second.t0, second.t1), (0.125, 0.625));
    }

    #[test]
    fn reversed_match_reencodes_points_indices_and_parameters() {
        let mut flipped = vside("b", 1.0, [2, 3], [0.125, 0.625]);
        flipped.p0 = [1.0, 1.0];
        flipped.p1 = [1.0, 0.0];
        let sides = vec![vside("a", -1.0, [0, 1], [0.0, 1.0]), flipped];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        let (first, second, dist) = &matches[0];
        assert_eq!(first.pair, "a");
        assert_eq!(second.pair, "b");
        assert_eq!(dist, &0.0);
        assert_eq!((second.p0, second.p1), ([1.0, 0.0], [1.0, 1.0]));
        assert_eq!((second.i0, second.i1), (3, 2));
        assert_eq!((second.t0, second.t1), (0.375, 0.875));
    }

    #[test]
    fn mirrored_sides_sharing_pair_id_yield_no_match() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("a", 1.0, [2, 3], [0.0, 1.0]),
        ];
        assert!(match_borders(&sides, 0.0, 0.25).is_empty());
    }

    #[test]
    fn equal_distance_keeps_first_encounter() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.125, [2, 3], [0.0, 1.0]),
            vside("c", 0.875, [4, 5], [0.0, 1.0]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 2);
        assert_eq!(matches[0].1.pair, "b");
        assert_eq!((matches[0].1.i0, matches[0].1.i1), (2, 3));
        assert_eq!(matches[1].0.pair, "c");
    }

    #[test]
    fn offset_equal_to_epsilon_is_accepted() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.25, [2, 3], [0.0, 1.0]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        assert_eq!(matches[0].2, 0.25);
    }

    #[test]
    fn reflected_portions_keep_their_own_affine_coordinates() {
        // Hobby (16) matches points on two source portions. Their parent
        // edges can have different parameter intervals after subdivision.
        let system =
            super::super::System::new(vec![[-2.0, 0.0], [-4.0, 4.0], [2.0, 0.0], [4.0, 4.0]], 16.0);
        let first = Side {
            pair: "a".into(),
            p0: [-2.5, 1.0],
            p1: [-3.5, 3.0],
            i0: 0,
            i1: 1,
            t0: 0.25,
            t1: 0.75,
        };
        let second = Side {
            pair: "b".into(),
            p0: [3.0, 2.0],
            p1: [3.8, 3.6],
            i0: 2,
            i1: 3,
            t0: 0.5,
            t1: 0.9,
        };
        let rows = symmetry_rows(&system, &[(first, second, 0.0)], 0.0, 0.0, 16.0);
        // Mean endpoint weights on the second edge are 0.3 and 0.7;
        // borrowing the first edge's interval would incorrectly give 1:1.
        assert!((rows[0].0[4] / rows[0].0[6] - 3.0 / 7.0).abs() < 1e-12);
        // The two portions span 0.5 and 0.4 of their parent edges.
        assert!((rows[1].0[4] / rows[1].0[0] - 0.8).abs() < 1e-12);
    }
}

#[cfg(test)]
mod parity_decision_tests {
    use super::super::geometry::Portion;
    use super::super::PreppedInfo;
    use super::decide_parity_target;

    fn info_with_widths(src_widths: Vec<f64>) -> PreppedInfo {
        let blank = Portion {
            contour: 0,
            seg: 0,
            t0: 0.0,
            t1: 0.0,
            p0: [0.0, 0.0],
            p1: [0.0, 0.0],
            i0: 0,
            i1: 0,
            hidden: false,
            unknown: false,
        };
        PreppedInfo {
            id: String::new(),
            a: blank.clone(),
            b: blank,
            normal: [0.0, 0.0],
            stations: Vec::new(),
            src_widths,
            fit_widths: Vec::new(),
            arc: 0.0,
            span_lo: 0.0,
            span_hi: 0.0,
            bound: 0.0,
            prefix: 0.0,
            peak: 0.0,
            rounded_peak: None,
            pairs: Vec::new(),
            feet: serde_json::Value::Null,
        }
    }

    #[test]
    fn no_waist_rejects_nonpositive_and_nan_prediction() {
        let empty: Vec<PreppedInfo> = Vec::new();
        for predicted in [0.0, -1.0, f64::NAN] {
            assert!(matches!(
                decide_parity_target(0.0, predicted, 0.0, &empty),
                Err("no-waist")
            ));
        }
    }

    #[test]
    fn unequal_groups_average_with_nonzero_rel() {
        let prepped = [
            info_with_widths(vec![1.0, 3.0]),
            info_with_widths(vec![5.0]),
        ];
        assert_eq!(decide_parity_target(0.25, 3.85, 0.1, &prepped), Ok(0.0));
        assert_eq!(decide_parity_target(0.25, 2.8, -0.2, &prepped), Ok(0.5));
    }

    #[test]
    fn odd_width_targets_pixel_center_with_lower_tie() {
        for width in [0.5, 1.0, 3.0] {
            let prepped = [info_with_widths(vec![width])];
            assert_eq!(decide_parity_target(0.0, width, 0.0, &prepped), Ok(-0.5));
            assert_eq!(decide_parity_target(0.25, width, 0.0, &prepped), Ok(0.5));
        }
    }

    #[test]
    fn even_width_targets_boundary() {
        let prepped = [info_with_widths(vec![2.0])];
        assert_eq!(decide_parity_target(0.0, 2.0, 0.0, &prepped), Ok(0.0));
        assert_eq!(decide_parity_target(0.5, 2.0, 0.0, &prepped), Ok(1.0));
        assert_eq!(decide_parity_target(-0.25, 2.0, 0.0, &prepped), Ok(0.0));
        let axis = ((1_u64 << 53) - 1) as f64;
        assert_eq!(decide_parity_target(axis, 2.0, 0.0, &prepped), Ok(axis));
    }

    #[test]
    fn width_mismatch_is_ambiguous() {
        let prepped = [info_with_widths(vec![3.0])];
        assert!(matches!(
            decide_parity_target(0.0, 2.0, 0.0, &prepped),
            Err("parity-ambiguous")
        ));
    }

    #[test]
    fn subhalf_widths_fall_through_to_ambiguous() {
        let prepped = [info_with_widths(vec![0.25])];
        assert!(matches!(
            decide_parity_target(0.0, 0.25, 0.0, &prepped),
            Err("parity-ambiguous")
        ));
    }
}
//! Shared constrained least-squares numeric core for diagonal fitting.
//!
//! Source: primal feasible active-set method for convex quadratic programs
//! with equality, inequality and box constraints (Forsgren, Gill and Wong,
//! 2015). Each search direction is the equality-nullspace least-squares
//! minimizer; the first blocking bound limits the step, and a negative
//! bound multiplier releases that constraint. Delivery is gated on primal
//! feasibility and the convex KKT normal-cone condition, never on matching
//! an alternate numerical implementation.
//!
//! Project adaptations: dense `Vec<f64>` rows matching the fitting systems;
//! fixed model thresholds below (no per-glyph tuning); `None` on unresolved
//! initialization or iteration limits so callers abstain. Runtime never uses
//! Python, SciPy, subprocesses or corpus corrections.

use nalgebra::{DMatrix, DVector};

/// Fixed model thresholds mirroring the prototype constants.
struct Tolerances {
    /// Primal step/zero norm (`tol`).
    primal: f64,
    /// Delivered equality residual gate (prototype `1e-8` for the convex
    /// path, `tol` for the bounded path).
    equality: f64,
    /// Relative KKT stationarity gate (prototype `1e-7` convex, `tol`
    /// bounded).
    stationarity: f64,
    /// Dual feasibility scale (`tol * (1 + |gradient|)`).
    dual: f64,
}

const BOUNDED_TOL: Tolerances = Tolerances {
    primal: 1e-9,
    equality: 1e-9,
    stationarity: 1e-9,
    dual: 1e-9,
};

const CONVEX_TOL: Tolerances = Tolerances {
    primal: 1e-9,
    equality: 1e-8,
    stationarity: 1e-7,
    dual: 1e-9,
};

/// Delivered-point inequality slack gate (prototype `min(slack) < -1e-8`
/// rejects the candidate). General inequalities keep this prototype band;
/// box sides keep the tighter internal primal gate.
const DELIVER_SLACK: f64 = 1e-8;

/// Solver evidence returned alongside the displacement.
#[derive(Clone, Debug)]
pub(super) struct QpInfo {
    pub iterations: usize,
    pub equality_error: f64,
    pub stationarity_error: f64,
    pub inequality_slack: f64,
    pub active: usize,
}

/// Minimum-norm least squares, NumPy `lstsq(rcond=None)` semantics.
///
/// Rank rule matches the prototype exactly: singular values above
/// `eps * max(m, n) * sigma_max` are kept; the solution is the minimum-norm
/// one in the free modes. Local copy keeps the numeric core reviewable in
/// one file; it duplicates no fitting state.
fn lstsq(a: &DMatrix<f64>, b: &DVector<f64>) -> DVector<f64> {
    LeastSquares::new(a).solve(b)
}

/// Factor once, solve new right-hand sides with the same arithmetic and rank
/// rule. This follows nalgebra's separation of SVD construction and solving:
/// https://docs.rs/nalgebra/0.35.0/nalgebra/linalg/struct.SVD.html
/// The explicit solve retains the original accumulation order.
struct LeastSquares {
    n: usize,
    factors: Option<(DMatrix<f64>, DMatrix<f64>, DVector<f64>, f64)>,
}

impl LeastSquares {
    fn new(a: &DMatrix<f64>) -> Self {
        let (m, n) = (a.nrows(), a.ncols());
        let zero = Self { n, factors: None };
        if m == 0 || n == 0 {
            return zero;
        }
        let svd = a.clone().svd(true, true);
        let sigmax = svd.singular_values.iter().cloned().fold(0.0_f64, f64::max);
        if !(sigmax > 0.0) {
            return zero;
        }
        let tol = f64::EPSILON * (m.max(n) as f64) * sigmax;
        let (Some(u), Some(vt)) = (svd.u, svd.v_t) else {
            return zero;
        };
        Self {
            n,
            factors: Some((u, vt, svd.singular_values, tol)),
        }
    }

    fn solve(&self, b: &DVector<f64>) -> DVector<f64> {
        let Some((u, vt, values, tol)) = &self.factors else {
            return DVector::zeros(self.n);
        };
        let utb: DVector<f64> = u.transpose() * b;
        let mut x = DVector::zeros(self.n);
        for (i, &s) in values.iter().enumerate() {
            if s > *tol {
                let c = utb[i] / s;
                for j in 0..self.n {
                    x[j] += vt[(i, j)] * c;
                }
            }
        }
        x
    }
}

fn dot(a: &[f64], b: &[f64]) -> f64 {
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

fn norm(v: &[f64]) -> f64 {
    v.iter().map(|x| x * x).sum::<f64>().sqrt()
}

/// One working-set row: equality, general inequality, or box side.
#[derive(Clone)]
enum WorkRow {
    /// Equality row, always active.
    Eq(Vec<f64>),
    /// Inequality `row . x >= lower`.
    Ineq(Vec<f64>, f64),
    /// Upper box side `x[i] <= bounds[i]`.
    Upper(usize),
    /// Lower box side `x[i] >= -bounds[i]`.
    Lower(usize),
}

impl WorkRow {
    fn coeffs(&self, n: usize) -> Vec<f64> {
        match self {
            WorkRow::Eq(row) | WorkRow::Ineq(row, _) => row.clone(),
            WorkRow::Upper(i) => {
                let mut row = vec![0.0; n];
                row[*i] = 1.0;
                row
            }
            WorkRow::Lower(i) => {
                let mut row = vec![0.0; n];
                row[*i] = -1.0;
                row
            }
        }
    }

    /// Constraint gradient with its sign restriction under the
    /// `L = f - λc, λ >= 0` convention: equalities stay free, while box
    /// sides enter through their `bound - x` form, negating the working
    /// coefficients.
    fn grad_row(&self, n: usize) -> (Vec<f64>, bool) {
        match self {
            WorkRow::Eq(row) => (row.clone(), false),
            WorkRow::Ineq(row, _) => (row.clone(), true),
            WorkRow::Upper(i) => {
                let mut row = vec![0.0; n];
                row[*i] = -1.0;
                (row, true)
            }
            WorkRow::Lower(i) => {
                // Lower side is x[i] >= -bound, i.e. c = x[i] + bound with
                // gradient +e[i]; the working coefficient carries the
                // opposite sign and must not leak into the multiplier.
                let mut row = vec![0.0; n];
                row[*i] = 1.0;
                (row, true)
            }
        }
    }
}

/// Immutable direction system for one ordered working set. A full step only
/// changes the residual; adding or releasing a constraint invalidates both
/// factors. Nothing is retained across separate active-set solves.
struct DirectionSystem {
    zmat: DMatrix<f64>,
    reduced: LeastSquares,
}

impl DirectionSystem {
    fn new(
        _a: &[Vec<f64>],
        active: &[WorkRow],
        n: usize,
        objective: &SparseObjective,
    ) -> Option<Self> {
        let k = active.len();
        // Padding recovers the full V factor, including the nullspace modes.
        let wrows = {
            let m = k.max(n);
            let mut flat = vec![0.0; m * n];
            for (r, work) in active.iter().enumerate() {
                let w = work.coeffs(n);
                for (j, v) in w.iter().enumerate() {
                    flat[r * n + j] = *v;
                }
            }
            DMatrix::from_row_slice(m, n, &flat)
        };
        let svd = wrows.svd(false, true);
        let sigmax = svd.singular_values.iter().cloned().fold(0.0_f64, f64::max);
        let cutoff = (k.max(n) as f64) * sigmax * 1e-12;
        let rank = if !(sigmax > 0.0) {
            0
        } else {
            svd.singular_values.iter().filter(|s| **s > cutoff).count()
        };
        let vt = svd.v_t?;
        let zn = n - rank;
        let mut zmat = DMatrix::zeros(n, zn);
        for (c, r) in (rank..n).enumerate() {
            for i in 0..n {
                zmat[(i, c)] = vt[(r, i)];
            }
        }
        let az = objective.project(&zmat);
        Some(Self {
            zmat,
            reduced: LeastSquares::new(&az),
        })
    }
}

/// Primal feasible active-set solve.
///
/// Minimizes `1/2 |A x - b|^2` subject to `G x = h`, `C x >= lower` and
/// `|x[i]| <= bounds[i]`. Equality pairs carry `(row, rhs)` with `rhs`
/// already on the constant side. Returns `None` when initialization is
/// infeasible, a row is degenerate, or the iteration budget
/// (20 * max(1, n), per the prototype) is exhausted.
fn active_set(
    tol: &Tolerances,
    a: &[Vec<f64>],
    b: &[f64],
    equalities: &[(Vec<f64>, f64)],
    inequalities: &[(Vec<f64>, f64)],
    bounds: &[f64],
    strict_init: bool,
) -> Option<(Vec<f64>, QpInfo)> {
    let n = a
        .iter()
        .map(Vec::len)
        .chain(equalities.iter().map(|(r, _)| r.len()))
        .chain(inequalities.iter().map(|(r, _)| r.len()))
        .chain(std::iter::once(bounds.len()))
        .max()?;
    if n == 0 || bounds.len() != n {
        return None;
    }
    if bounds.iter().any(|v| !v.is_finite() || *v <= 0.0) {
        return None;
    }
    for row in a
        .iter()
        .chain(equalities.iter().map(|(r, _)| r))
        .chain(inequalities.iter().map(|(r, _)| r))
    {
        if row.len() != n || !row.iter().all(|v| v.is_finite()) {
            return None;
        }
    }
    if b.len() != a.len() || !b.iter().all(|v| v.is_finite()) {
        return None;
    }

    // Normalize equality rows; exact-zero rows must carry zero constants.
    let mut eq: Vec<(Vec<f64>, f64)> = Vec::with_capacity(equalities.len());
    for (row, rhs) in equalities {
        let scale = norm(row);
        if scale <= 0.0 {
            if rhs.abs() > tol.primal {
                return None;
            }
            continue;
        }
        eq.push((row.iter().map(|v| v / scale).collect(), rhs / scale));
    }
    // Normalize inequality rows the same way.
    let mut ie: Vec<(Vec<f64>, f64)> = Vec::with_capacity(inequalities.len());
    for (row, lower) in inequalities {
        let scale = norm(row);
        if scale <= 0.0 {
            if *lower > tol.primal {
                return None;
            }
            continue;
        }
        ie.push((row.iter().map(|v| v / scale).collect(), lower / scale));
    }

    // Minimum-norm particular solution of the equalities.
    let x = if eq.is_empty() {
        vec![0.0; n]
    } else {
        let flat: Vec<f64> = eq.iter().flat_map(|(r, _)| r.iter().copied()).collect();
        let mat = DMatrix::from_row_slice(eq.len(), n, &flat);
        lstsq(
            &mat,
            &DVector::from_vec(eq.iter().map(|(_, h)| *h).collect()),
        )
        .iter()
        .copied()
        .collect()
    };
    if eq_error_max(&eq, &x) > tol.equality || x.iter().any(|v| !v.is_finite()) {
        return None;
    }
    if strict_init {
        // Original bounded path: the min-norm start must already respect
        // the box; no SLSQP-style repair applies here.
        if x.iter()
            .zip(bounds.iter())
            .any(|(v, limit)| v.abs() > limit + tol.primal)
        {
            return None;
        }
        solve_core(tol, a, b, &eq, &ie, bounds, x)
    } else {
        // Convex path: the original clips the start and lets the optimizer
        // repair, so a box- or inequality-violating min-norm start goes to
        // the elastic Phase I instead of being rejected outright.
        let Some(start) = elastic_start(tol, &eq, &ie, bounds, x) else {
            return None;
        };
        solve_core(tol, a, b, &eq, &ie, bounds, start)
    }
}

/// Primal feasible active-set core: nullspace steps with release from a
/// feasible start. Delivery stays gated on primal feasibility and the KKT
/// normal-cone check, so the core never certifies an infeasible point.
#[allow(clippy::too_many_arguments)]
fn solve_core(
    tol: &Tolerances,
    a: &[Vec<f64>],
    b: &[f64],
    eq: &[(Vec<f64>, f64)],
    ie: &[(Vec<f64>, f64)],
    bounds: &[f64],
    mut x: Vec<f64>,
) -> Option<(Vec<f64>, QpInfo)> {
    let n = bounds.len();
    // Objective gradient pieces: Q = A'A, q = -A'b, kept factored.
    let at_rows: Vec<Vec<f64>> = (0..n)
        .map(|j| a.iter().map(|row| row[j]).collect())
        .collect();
    let objective = SparseObjective::new(a, n);
    let at_b: Vec<f64> = at_rows.iter().map(|row| dot(row, b)).collect();
    let gradient = |x: &[f64]| {
        let ax = objective.product(x);
        let at_ax = objective.transpose_product(&at_rows, &ax);
        let d: Vec<f64> = at_ax.iter().zip(&at_b).map(|(v, w)| v - w).collect();
        (d, ax)
    };

    // Working set: all equalities plus active bounds/inequalities.
    let mut active: Vec<WorkRow> = eq.iter().map(|(r, _)| WorkRow::Eq(r.clone())).collect();
    let mut direction = None;
    let cap = 20 * n.max(1);
    for iteration in 0..cap {
        let (d, ax) = gradient(&x);
        let dnorm = norm(&d);
        // Equality-nullspace least squares supplies each direction, in the
        // prototype's explicit form: with P the orthoprojector onto ker W
        // (V rows past the 1e-12 working-set rank), p = P lstsq(A P, b - Ax).
        // No Gram matrix A'A is ever formed, so the step keeps the
        // conditioning of the prototype's nullspace solve.
        let k = active.len();
        // Nullspace basis from the zero-padded working set: padding to
        // max(k, n) rows recovers the full n x n V factor from the thin
        // native SVD, and the modes at or below the 1e-12 rank cutoff form
        // Z. The projector form P = I - Vr'Vr is never used: at full rank
        // its all-epsilon entries read as full rank in the reduced solve.
        if direction.is_none() {
            direction = Some(DirectionSystem::new(a, &active, n, &objective)?);
        }
        let system = direction.as_ref()?;
        let zmat = &system.zmat;
        let zn = zmat.ncols();

item.aggregated_output:
    );
    let symmetry = symmetry_rows(&system, &matches, axis_src, f_k, size_px);
    // The distortion and relative-width rows remain soft; symmetry rows
    // alone constrain the parity phase (prototype `group != symmetry`).
    let width_rows: Vec<(&Vec<f64>, f64)> = system
        .rows
        .iter()
        .map(|(_, row, constant)| (row, *constant))
        .collect();
    let base = parsed.oncurve.clone();
    let upstream = fitted_coords.clone();
    let gaps: Vec<f64> = upstream
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let mut columns: Vec<usize> = var_verts
        .iter()
        .filter(|v| !fixed.contains_key(&(**v, 0)))
        .map(|v| 2 * *v)
        .collect();
    columns.sort();
    if columns.is_empty() {
        return Ok(abstain(
            original_upstream,
            "no-horizontal-freedom",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    let project = |row: &[f64], constant: f64| -> (Vec<f64>, f64) {
        (
            columns.iter().map(|c| row[*c]).collect(),
            -dot(row, &gaps) - constant,
        )
    };
    let a_mat: Vec<Vec<f64>> = width_rows.iter().map(|(r, c)| project(r, *c).0).collect();
    let b_vec: Vec<f64> = width_rows.iter().map(|(r, c)| project(r, *c).1).collect();
    let g_mat: Vec<Vec<f64>> = symmetry.iter().map(|(r, c)| project(r, *c).0).collect();
    let h_vec: Vec<f64> = symmetry.iter().map(|(r, c)| project(r, *c).1).collect();
    let bounds: Vec<f64> = columns
        .iter()
        .map(|col| {
            let v = col / 2;
            prepped
                .iter()
                .filter(|info| [info.a.i0, info.a.i1, info.b.i0, info.b.i1].contains(&v))
                .map(|info| info.bound)
                .fold(f64::INFINITY, f64::min)
        })
        .collect();
    let Some((delta, qp_info)) = qp::bounded_equalities(&a_mat, &b_vec, &g_mat, &h_vec, &bounds)
    else {
        return Ok(abstain(
            original_upstream,
            "phase-bounds-incompatible",
            serde_json::json!({"skipped": skipped_json}),
        ));
    };
    let mut flat_delta = vec![0.0; gaps.len()];
    for (k, col) in columns.iter().enumerate() {
        flat_delta[*col] = delta[k];
    }
    let mut peaks: HashMap<String, f64> = HashMap::new();
    for info in &prepped {
        let peak = [info.a.i0, info.a.i1, info.b.i0, info.b.i1]
            .iter()
            .map(|v| flat_delta[2 * *v].hypot(flat_delta[2 * *v + 1]))
            .fold(0.0, f64::max);
        peaks.insert(info.id.clone(), peak);
    }
    let over: Vec<&super::PreppedInfo> = prepped
        .iter()
        .filter(|info| peaks[&info.id] > info.bound)
        .collect();
    if !over.is_empty()
        && over
            .iter()
            .map(|info| peaks[&info.id] - info.bound)
            .fold(0.0, f64::max)
            > 1e-9
    {
        return Ok(abstain(
            original_upstream,
            "movement-budget",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    for info in prepped.iter_mut() {
        info.peak = peaks[&info.id];
    }
    let table = geometry::index_map(original_upstream);
    let mut candidate = original_upstream.to_vec();
    let flat_up: Vec<f64> = upstream.iter().flat_map(|p| [p[0], p[1]]).collect();
    let flat_cand: Vec<f64> = flat_up
        .iter()
        .zip(flat_delta.iter())
        .map(|(u, d)| u + d)
        .collect();
    let mut sorted_verts: Vec<usize> = var_verts.iter().copied().collect();
    sorted_verts.sort();
    for v in sorted_verts {
        let Some(pos) = table.get(v).copied().flatten() else {
            continue;
        };
        for axis in 0..2 {
            if fixed.contains_key(&(v, axis)) {
                continue;
            }
            let value = flat_cand[2 * v + axis];
            if value == flat_up[2 * v + axis] {
                continue;
            }
            let rounded = geometry::round_26_6(value) as f32;
            match &mut candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                }
                FittedCommand::QuadTo(x1, y1, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1);
                }
                FittedCommand::CurveTo(x1, y1, x2, y2, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1, x2, y2);
                }
                FittedCommand::Close => {}
            }
        }
    }
    if candidate == original_upstream {
        return Ok(abstain(
            original_upstream,
            "no-movement",
            serde_json::json!({"skipped": skipped_json}),
        ));
    }
    let mut validity = validate(
        &parsed,
        &fitted,
        original_upstream,
        &candidate,
        &portions,
        &mut prepped,
        &pins,
        &owned,
        source,
    );
    if validity.ok {
        if let Err(reason) = geometry::curve_sweep_ok(
            &parsed,
            &fitted_coords,
            &candidate,
            &geometry::curve_controls(&fitted),
        ) {
            validity.ok = false;
            validity.stage = reason.to_string();
        }
    }
    // Exact f32-bits pins: coordinate equality also holds across signed
    // zero, but bit identity is the upstream contract here.
    if validity.ok {
        let cand_table = geometry::index_map(&candidate);
        let mut inverted: HashMap<usize, usize> = HashMap::new();
        for (idx, pos) in cand_table.iter().enumerate() {
            if let Some(p) = pos {
                inverted.insert(*p, idx);
            }
        }
        let mut bits_ok = true;
        for (pos, cmd) in candidate.iter().enumerate() {
            let Some(&idx) = inverted.get(&pos) else {
                continue;
            };
            for axis in owned.iter().copied() {
                if bits_of(cmd, axis) != bits_of(&original_upstream[pos], axis) {
                    let _ = idx;
                    bits_ok = false;
                }
            }
        }
        for pin in pins.iter() {
            let Some(pos) = cand_table.get(*pin).copied().flatten() else {
                continue;
            };
            for axis in 0..2 {
                if bits_of(&candidate[pos], axis) != bits_of(&original_upstream[pos], axis) {
                    bits_ok = false;
                }
            }
        }
        if !bits_ok {
            validity.ok = false;
            validity.stage = "pins-bits-changed".to_string();
        }
    }
    let match_cost = |flat: &[f64]| -> f64 {
        width_rows
            .iter()
            .map(|(row, constant)| (dot(row, flat) + constant).powi(2))
            .sum()
    };
    let sym_cost = |flat: &[f64]| -> f64 {
        symmetry
            .iter()
            .map(|(row, constant)| (dot(row, flat) + constant).powi(2))
            .sum()
    };
    let flat_base_up: Vec<f64> = upstream
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let cost_upstream = match_cost(&flat_base_up);
    let sym_upstream = sym_cost(&flat_base_up);
    let parsed_cand = geometry::parse_commands(&candidate);
    let (cost_candidate, sym_candidate) = match parsed_cand {
        Ok(cand) => {
            let flat: Vec<f64> = cand
                .oncurve
                .iter()
                .zip(base.iter())
                .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
                .collect();
            (Some(match_cost(&flat)), Some(sym_cost(&flat)))
        }
        Err(()) => (None, None),
    };
    let cost_ok = cost_candidate.is_some_and(|c| c < cost_upstream);
    let symmetry_ok = sym_candidate.is_some_and(|c| c < sym_upstream);
    validity.cost_upstream = Some(cost_upstream);
    validity.cost_candidate = cost_candidate;
    validity.cost_ok = cost_ok;
    if !cost_ok {
        validity.ok = false;
        validity.stage = "no-cost-decrease".to_string();
    } else if !symmetry_ok {
        validity.ok = false;
        validity.stage = "no-symmetry-decrease".to_string();
    }
    let achieved = achieved_widths(&prepped, &candidate);
    let widths = mean_widths(&achieved);
    let diagnostics = serde_json::json!({
        "epsilon": EPS_PARITY,
        "axis_src": axis_src,
        "qp": {"iterations": qp_info.iterations, "equality_error": qp_info.equality_error,
                "stationarity_error": qp_info.stationarity_error, "active": qp_info.active},
        "locus": {"cmin": locus.cmin, "cmax": locus.cmax,
                  "n": locus.n, "skipped_slabs": locus.skipped},
        "waist": {"width": waist.width, "mid": waist.mid, "level": waist.level,
                  "predicted": predicted, "rel_med": rel_med},
        "parity_target": target,
        "f_k": f_k,
        "matches": matches.len(),
        "symmetry_upstream": sym_upstream,
        "symmetry_candidate": sym_candidate,
        "symmetry_ok": symmetry_ok,
    });
    if !validity.ok {
        let fallback = achieved_widths(&prepped, original_upstream);
        return Ok(FitResult {
            commands: original_upstream.to_vec(),
            applied: false,
            reason: "invalid-candidate".to_string(),
            diagnostics: serde_json::json!({
                "validity": super::validity_json(&validity),
                "pairs": achieved_json(&prepped, &achieved),
                "skipped": skipped_json,
                "diagnostics": diagnostics,
                "movement": peaks.values().cloned().fold(0.0, f64::max),
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "widths": mean_widths(&fallback),
                "reference": reference_meta(reference),
            }),
        });
    }
    Ok(FitResult {
        commands: candidate,
        applied: true,
        reason: "applied-joint".to_string(),
        diagnostics: serde_json::json!({
            "validity": super::validity_json(&validity),
            "pairs": achieved_json(&prepped, &achieved),
            "skipped": skipped_json,
            "diagnostics": diagnostics,
            "movement": peaks.values().cloned().fold(0.0, f64::max),
            "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
            "size_px": size_px,
            "widths": widths,
            "reference": reference_meta(reference),
        }),
    })
}

impl AxisLocus {
    fn mid(&self) -> f64 {
        (self.cmin + self.cmax) / 2.0
    }
}

#[cfg(test)]
mod correspondence_tests {
    use super::*;

    fn vside(pair: &str, x: f64, indices: [usize; 2], interval: [f64; 2]) -> Side {
        Side {
            pair: pair.into(),
            p0: [x, 0.0],
            p1: [x, 1.0],
            i0: indices[0],
            i1: indices[1],
            t0: interval[0],
            t1: interval[1],
        }
    }

    #[test]
    fn forward_match_orders_sides_and_keeps_metadata() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.0, [2, 3], [0.125, 0.625]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        let (first, second, dist) = &matches[0];
        assert_eq!(first.pair, "a");
        assert_eq!(second.pair, "b");
        assert_eq!(dist, &0.0);
        assert_eq!(second.p0, [1.0, 0.0]);
        assert_eq!(second.p1, [1.0, 1.0]);
        assert_eq!((second.i0, second.i1), (2, 3));
        assert_eq!((second.t0, second.t1), (0.125, 0.625));
    }

    #[test]
    fn reversed_match_reencodes_points_indices_and_parameters() {
        let mut flipped = vside("b", 1.0, [2, 3], [0.125, 0.625]);
        flipped.p0 = [1.0, 1.0];
        flipped.p1 = [1.0, 0.0];
        let sides = vec![vside("a", -1.0, [0, 1], [0.0, 1.0]), flipped];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        let (first, second, dist) = &matches[0];
        assert_eq!(first.pair, "a");
        assert_eq!(second.pair, "b");
        assert_eq!(dist, &0.0);
        assert_eq!((second.p0, second.p1), ([1.0, 0.0], [1.0, 1.0]));
        assert_eq!((second.i0, second.i1), (3, 2));
        assert_eq!((second.t0, second.t1), (0.375, 0.875));
    }

    #[test]
    fn mirrored_sides_sharing_pair_id_yield_no_match() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("a", 1.0, [2, 3], [0.0, 1.0]),
        ];
        assert!(match_borders(&sides, 0.0, 0.25).is_empty());
    }

    #[test]
    fn equal_distance_keeps_first_encounter() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.125, [2, 3], [0.0, 1.0]),
            vside("c", 0.875, [4, 5], [0.0, 1.0]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 2);
        assert_eq!(matches[0].1.pair, "b");
        assert_eq!((matches[0].1.i0, matches[0].1.i1), (2, 3));
        assert_eq!(matches[1].0.pair, "c");
    }

    #[test]
    fn offset_equal_to_epsilon_is_accepted() {
        let sides = vec![
            vside("a", -1.0, [0, 1], [0.0, 1.0]),
            vside("b", 1.25, [2, 3], [0.0, 1.0]),
        ];
        let matches = match_borders(&sides, 0.0, 0.25);
        assert_eq!(matches.len(), 1);
        assert_eq!(matches[0].2, 0.25);
    }

    #[test]
    fn reflected_portions_keep_their_own_affine_coordinates() {
        // Hobby (16) matches points on two source portions. Their parent
        // edges can have different parameter intervals after subdivision.
        let system =
            super::super::System::new(vec![[-2.0, 0.0], [-4.0, 4.0], [2.0, 0.0], [4.0, 4.0]], 16.0);
        let first = Side {
            pair: "a".into(),
            p0: [-2.5, 1.0],
            p1: [-3.5, 3.0],
            i0: 0,
            i1: 1,
            t0: 0.25,
            t1: 0.75,
        };
        let second = Side {
            pair: "b".into(),
            p0: [3.0, 2.0],
            p1: [3.8, 3.6],
            i0: 2,
            i1: 3,
            t0: 0.5,
            t1: 0.9,
        };
        let rows = symmetry_rows(&system, &[(first, second, 0.0)], 0.0, 0.0, 16.0);
        // Mean endpoint weights on the second edge are 0.3 and 0.7;
        // borrowing the first edge's interval would incorrectly give 1:1.
        assert!((rows[0].0[4] / rows[0].0[6] - 3.0 / 7.0).abs() < 1e-12);
        // The two portions span 0.5 and 0.4 of their parent edges.
        assert!((rows[1].0[4] / rows[1].0[0] - 0.8).abs() < 1e-12);
    }
}

