                if worst_val < -tol.dual * scale {
                    // Release the most negative bound multiplier and continue.
                    active.remove(r);
                    direction = None;
                    continue;
                }
            }
            return None;
        }
        // Step to the first blocking bound or inequality.
        let mut step = 1.0f64;
        let mut blocking: Option<WorkRow> = None;
        for (i, &pi) in p.iter().enumerate() {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Upper(j) | WorkRow::Lower(j) if *j == i))
            {
                continue;
            }
            if pi > tol.primal {
                let dist = (bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Upper(i));
                }
            } else if pi < -tol.primal {
                let dist = (-bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Lower(i));
                }
            }
        }
        for (row, lower) in ie {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Ineq(r, l) if r == row && l == lower))
            {
                continue;
            }
            let denom = dot(row, &p);
            if denom < -tol.primal {
                let dist = (lower - dot(row, &x)) / denom;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Ineq(row.clone(), *lower));
                }
            }
        }
        for (v, pi) in x.iter_mut().zip(p.iter()) {
            *v += step * pi;
        }
        // A recorded blocker was the strict minimum, so the step stops on
        // it; a full step leaves the working set unchanged.
        if let Some(work) = blocking {
            active.push(work);
            direction = None;
        }
    }
    None
}

fn eq_error_max(eq: &[(Vec<f64>, f64)], x: &[f64]) -> f64 {
    eq.iter()
        .map(|(row, h)| (dot(row, x) - h).abs())
        .fold(0.0_f64, f64::max)
}

/// Elastic Phase I: minimize t subject to Gx = h, Cx + t >= lower,
/// |x| <= bounds + t and t >= 0.
///
/// The auxiliary program has the known feasible start (x_eq, t0) with t0
/// the worst violation at the equality min-norm point, and its optimum is
/// t* = 0 exactly for feasible originals. It runs through the real
/// active-set core with release, so no row is ever frozen in: constraints
/// leave the working set by the same multiplier rule as the main solve.
/// Returns the repaired x when t* certifies feasibility; otherwise None,
/// which is the infeasible certificate the main solve would otherwise lack.
fn elastic_start(
    tol: &Tolerances,
    eq: &[(Vec<f64>, f64)],
    ie: &[(Vec<f64>, f64)],
    bounds: &[f64],
    x0: Vec<f64>,
) -> Option<Vec<f64>> {
    let n = x0.len();
    let mut t0 = 0.0f64;
    for (row, lower) in ie {
        t0 = t0.max(lower - dot(row, &x0));
    }
    for (v, limit) in x0.iter().zip(bounds.iter()) {
        t0 = t0.max(v.abs() - limit);
    }
    if !t0.is_finite() {
        return None;
    }
    let mut t_row = vec![0.0; n + 1];
    t_row[n] = 1.0;
    let eq_el: Vec<(Vec<f64>, f64)> = eq
        .iter()
        .map(|(w, h)| ([w.clone(), vec![0.0]].concat(), *h))
        .collect();
    let mut ie_el: Vec<(Vec<f64>, f64)> = Vec::with_capacity(ie.len() + 2 * n + 1);
    for (w, l) in ie {
        ie_el.push(([w.clone(), vec![1.0]].concat(), *l));
    }
    for (i, limit) in bounds.iter().enumerate() {
        let mut up = vec![0.0; n + 1];
        up[i] = -1.0;
        up[n] = 1.0;
        ie_el.push((up, -limit));
        let mut dn = vec![0.0; n + 1];
        dn[i] = 1.0;
        dn[n] = 1.0;
        ie_el.push((dn, -limit));
    }
    ie_el.push((t_row.clone(), 0.0));
    let eb: Vec<f64> = bounds
        .iter()
        .map(|l| l + t0 + 1e-6)
        .chain(std::iter::once(t0 + 1e-6))
        .collect();
    let mut start = x0;
    start.push(t0);
    let (xt, _) = solve_core(tol, &[t_row], &[0.0], &eq_el, &ie_el, &eb, start)?;
    // The handoff band admits near-zero slack only; delivery itself stays
    // gated on the prototype bands inside the main solve.
    if !(xt[n] <= 1e-7) {
        return None;
    }
    Some(xt[..n].to_vec())
}

/// Feasible primal active-set least squares with equality and box limits.
///
/// Native port of the joint-model `_bounded_equalities`: `a x = b` in the
/// least-squares sense subject to `g x = h` and `|x[i]| <= bounds[i]`.
/// Returns the displacement and solver evidence, or `None` when
/// initialization is infeasible or the iteration budget is exhausted.
pub(super) fn bounded_equalities(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    bounds: &[f64],
) -> Option<(Vec<f64>, QpInfo)> {
    active_set(
        &BOUNDED_TOL,
        a,
        b,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &[],
        bounds,
        true,
    )
}

/// Fixed convex least squares with linear constraints and box bounds.
///
/// Native port of the attached-model `_convex_qp`: minimizes
/// `1/2 |a x - b|^2` subject to `g x = h`, `c x >= lower` and
/// `|x| <= bound`. SciPy SLSQP supplies the prototype's numerical
/// candidate; this independent active-set implementation targets the same
/// constrained minimizer, gated by primal feasibility and the KKT
/// normal-cone check. Any rounding-level difference against an alternate
/// algorithm is diagnosed from these errors, never patched with offsets.
pub(super) fn convex_qp(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    c: &[Vec<f64>],
    lower: &[f64],
    bound: f64,
) -> Option<(Vec<f64>, QpInfo)> {
    let Some(n) = a
        .iter()
        .map(Vec::len)
        .chain(g.iter().map(Vec::len))
        .chain(c.iter().map(Vec::len))
        .max()
    else {
        return None;
    };
    // Prototype spectral normalization: the objective runs at
    // max(1, ||A||_2) so the SLSQP numerics and the KKT gates share one
    // scale. The minimizer is unchanged; the reported errors live in the
    // scaled system exactly as in the prototype.
    let scale = if a.is_empty() {
        1.0
    } else {
        let flat: Vec<f64> = a.iter().flat_map(|r| r.iter().copied()).collect();
        let normed = DMatrix::from_row_slice(a.len(), n, &flat);
        normed
            .svd(false, false)
            .singular_values
            .iter()
            .cloned()
            .fold(0.0_f64, f64::max)
            .max(1.0)
    };
    let a_scaled: Vec<Vec<f64>> = a
        .iter()
        .map(|r| r.iter().map(|v| v / scale).collect())
        .collect();
    let b_scaled: Vec<f64> = b.iter().map(|v| v / scale).collect();
    active_set(
        &CONVEX_TOL,
        &a_scaled,
        &b_scaled,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &c.iter()
            .zip(lower.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &vec![bound; n],
        false,
    )
}

// NIST Sparse BLAS matrix/vector and matrix/matrix operations:
// https://math.nist.gov/spblas/ . Exact-zero supports retain ascending
// accumulation order. Finite operands and nonzero finite results permit
// omitted zero products; otherwise the original dense dot retains signed
// zero, overflow and exceptional arithmetic. No approximate sparsity.
struct SparseObjective<'a> {
    dense: &'a [Vec<f64>],
    rows: Vec<Vec<(usize, f64)>>,
    }
    let mut ring = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) || var_verts.contains(&j) {
                ring.insert((i, j));
            }
        }
    }
    let mut ring_sorted: Vec<(usize, usize)> = ring.into_iter().collect();
    ring_sorted.sort();
    for (i, j) in ring_sorted {
        let _ = system.edge(i, j);
    }
    let base = parsed.oncurve.clone();
    let upstream = fitted_coords.to_vec();
    let shift: Vec<f64> = base
        .iter()
        .zip(upstream.iter())
        .flat_map(|(b, u)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for (group, row, constant) in system.rows.iter_mut() {
        match group {
            RowGroup::Position | RowGroup::Stretch | RowGroup::Bend => {
                let dot: f64 = row.iter().zip(shift.iter()).map(|(r, s)| r * s).sum();
                *constant -= dot;
            }
            RowGroup::InkMatch => {}
        }
    }
    for info in prepped.iter_mut() {
        let ta = |frac: f64| Sample::affine(info.a.i0, 1.0 - frac, info.a.i1, frac);
        let tb = |frac: f64| Sample::affine(info.b.i0, 1.0 - frac, info.b.i1, frac);
        let mut station_pairs = Vec::new();
        let mut ok = true;
        for st in &info.stations {
            let fa = info.a.t0 + (info.a.t1 - info.a.t0) * st.hit.sa;
            let fb = info.b.t0 + (info.b.t1 - info.b.t0) * st.hit.sb;
            match system.pair(&ta(fa), &tb(fb), info.arc, st.hit.center) {
                Ok(p) => station_pairs.push(p),
                Err(()) => {
                    ok = false;
                    break;
                }
            }
        }
        if !ok {
            continue;
        }
        info.pairs = Vec::with_capacity(station_pairs.len());
        for ((error, width, tangent), st) in station_pairs.into_iter().zip(info.stations.iter()) {
            info.pairs.push((error.clone(), width, tangent));
            for anchor in anchors {
                // Hobby (17) couples through the acute meeting angle: spine
                // order carries no orientation, so only the run side is
                // flipped toward the anchor; the reference stays unchanged.
                let run_tangent = acute(tangent, anchor.tangent);
                let psi = width_weight(
                    width,
                    anchor.source_width,
                    run_tangent,
                    anchor.tangent,
                    size_px,
                );
                let weight = info.arc * anchor.length * psi;
                let scaled: Vec<f64> = error.iter().map(|x| x * weight.sqrt()).collect();
                system
                    .rows
                    .push((RowGroup::InkMatch, scaled, anchor.rel * weight.sqrt()));
            }
            let _ = st;
        }
    }
    let mut fixed: HashMap<(usize, usize), f64> = HashMap::new();
    let gaps: Vec<[f64; 2]> = upstream
        .iter()
        .zip(base.iter())
        .map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for &v in pins {
        fixed.insert((v, 0), gaps[v][0]);
        fixed.insert((v, 1), gaps[v][1]);
    }
    for &v in &var_verts {
        for &axis in owned_axes {
            fixed.insert((v, axis), gaps[v][axis]);
        }
    }
    let mut far = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) && !var_verts.contains(&j) {
                far.insert(j);
            }
            if var_verts.contains(&j) && !var_verts.contains(&i) {
                far.insert(i);
            }
        }
    }
    for v in far {
        for axis in 0..2 {
            fixed.entry((v, axis)).or_insert(gaps[v][axis]);
        }
    }
    (system, fixed, var_verts)
}

/// Sorted vertex list for deterministic diagnostics; HashSet order is random.
fn sorted_verts(set: &HashSet<usize>) -> Vec<usize> {
    let mut out: Vec<usize> = set.iter().copied().collect();
    out.sort();
    out
}

fn abstain(upstream: &[FittedCommand], reason: &str, diagnostics: serde_json::Value) -> FitResult {
    FitResult {
        commands: upstream.to_vec(),
        applied: false,
        reason: reason.to_string(),
        diagnostics,
    }
}

/// Fit diagonal pairs of one glyph; exact upstream on abstention.
///
/// The joint system couples every diagonal station to every reference
/// anchor through (17) rows while source shape rows hold the outline;
/// shared vertices carry one unknown. Native-owned components and upright
/// anchors stay at upstream exactly. The candidate rounds moved coordinates
/// to 26.6 and must preserve orientation signs, upstream portion topology
/// and station ink, or the exact upstream commands return with the validity
/// evidence. Width-only: no grid arm, canonical exact crossings, interval
/// ownership.
pub fn fit(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    fit_with_analysis(
        source,
        upstream,
        size_px,
        reference,
        native_axes,
        &SourceAnalysis::new(source),
    )
}

pub(super) fn fit_with_analysis(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
    analysis: &SourceAnalysis<'_>,
) -> Result<FitResult, Error> {
    if !(size_px.is_finite() && size_px > 0.0) {
        return Err(fail("diagonal width requires finite positive size"));
    }
    if !geometry::check_correspondence(source, upstream) {
        return Ok(abstain(
            upstream,
            "no-correspondence",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (Ok(parsed), Ok(fitted)) = (analysis.parsed(), geometry::parse_commands(upstream)) else {
        return Ok(abstain(
            upstream,
            "malformed-commands",
            serde_json::json!({"size_px": size_px}),
        ));
    };
    if source.len() > MAX_COMMANDS || upstream.len() > MAX_COMMANDS {
        return Ok(abstain(
            upstream,
            "oversize-outline",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    if reference.anchors.is_empty() {
        return Ok(abstain(
            upstream,
            "no-reference-anchors",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (portions, curve_boxes, loops, flats) = analysis.visible();
    let (pairs, skipped) = analysis.pairs();
    let mut skipped = skipped.clone();
    let straights = loops.clone();
    let mut pins: HashSet<usize> = HashSet::new();
    for pair in geometry::upright_pairs(&pairs) {
        for side in [&pair.a, &pair.b] {
            pins.insert(side.i0);
            pins.insert(side.i1);
        }
    }
    for contour in &parsed.contours {
        for seg in contour {
            if seg.is_line() {
                continue;
            }
            let (a, b) = seg.endpoints();
            pins.insert(a);
            pins.insert(b);
        }
    }
    let owned: Vec<usize> = native_axes
        .iter()
        .enumerate()
        .filter(|(_, on)| **on)
        .map(|(axis, _)| axis)
        .collect();
    let borders = geometry::visible_borders(&portions);
    let fitted_coords = fitted.oncurve.clone();
    let mut prepped: Vec<PreppedInfo> = Vec::new();
    for pair in pairs {
        if geometry::upright_pairs(std::slice::from_ref(pair)).len() == 1 {
            skipped.push(geometry::Skipped {
                pair: (pair.a.seg, pair.b.seg),
                reason: "upright-anchor".to_string(),
            });
            continue;
        }
        match geometry::prepare_pair(
            pair,
            &borders,
            &loops,
            &straights,
            &flats,
            &curve_boxes,
            &fitted_coords,
            &geometry::curve_controls(&parsed),
        ) {
            Ok(prepped_pair) => {
                let bound = prepped_pair
                    .src_widths
                    .iter()
                    .cloned()
                    .fold(f64::INFINITY, f64::min)
                    / 2.0
                    - HEADROOM;
                if !(bound >= HEADROOM) {
                    skipped.push(geometry::Skipped {
                        pair: (pair.a.seg, pair.b.seg),
                        reason: "movement-budget-empty".to_string(),
                    });
                    continue;
                }
                let feet = serde_json::Value::Array(
                    pair.feet
                        .as_ref()
                        .map(|ranges| {
                            ranges
                                .iter()
                                .map(|r| serde_json::json!({"a": r.a, "b": r.b}))
                                .collect()
                        })
                        .unwrap_or_default(),
                );
                prepped.push(PreppedInfo {
                    id: prepped_pair.id,
                    a: prepped_pair.a,
                    b: prepped_pair.b,
                    normal: prepped_pair.normal,
                    stations: prepped_pair.stations,
                    src_widths: prepped_pair.src_widths,
                    fit_widths: prepped_pair.fit_widths,
                    arc: prepped_pair.arc,
                    span_lo: prepped_pair.span_lo,
                    span_hi: prepped_pair.span_hi,
                    bound,
                    prefix: 1.0,
                    peak: 0.0,
                    rounded_peak: None,
                    pairs: Vec::new(),
                    feet,
                });
            }
            Err(reason) => {
                skipped.push(geometry::Skipped {
                    pair: (pair.a.seg, pair.b.seg),
                    reason: reason.to_string(),
                });
            }
        }
    }
    let fixed_meta = serde_json::json!({
        "anchors": sorted_verts(&pins),
        "native_axes": [native_axes[0], native_axes[1]],
    });
    let skipped_json: Vec<serde_json::Value> = skipped
        .iter()
        .map(|s| serde_json::json!({"pair": [s.pair.0, s.pair.1], "reason": s.reason}))
        .collect();
    if prepped.is_empty() {
        return Ok(abstain(
            upstream,
            "all-abstained",
            serde_json::json!({"skipped": skipped_json, "fixed": fixed_meta}),
        ));
    }
    let (system, fixed, var_verts) = assemble(
        &parsed,
        &fitted_coords,
        &mut prepped,
        &reference.anchors,
        size_px,
        &pins,
        &owned,
    );
    let loose = solve_constrained(&system.rows, &fixed, parsed.oncurve.len());
    let base = parsed.oncurve.clone();
    let upstream_coords = fitted_coords.clone();
    let mut deltas: Vec<[f64; 2]> = (0..base.len())
        .map(|v| {
            [
                base[v][0] + loose[2 * v] - upstream_coords[v][0],
                base[v][1] + loose[2 * v + 1] - upstream_coords[v][1],
            ]
        })
        .collect();
    for info in prepped.iter_mut() {
        let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
        info.peak = verts
            .iter()
            .map(|&v| deltas[v][0].hypot(deltas[v][1]))
            .fold(0.0, f64::max);
    }
    let over: Vec<&PreppedInfo> = prepped
        .iter()
        .filter(|info| info.peak > info.bound)
        .collect();
    if !over.is_empty() {
        // Convex descent along the upstream-to-minimizer segment: the
        // objective decreases monotonically, so the feasible prefix keeps
        // every fixed coordinate exact while restoring the budget.
        let scale = over
            .iter()
            .map(|info| info.bound / info.peak)
            .fold(f64::INFINITY, f64::min);
        for d in deltas.iter_mut() {
            d[0] *= scale;
            d[1] *= scale;
        }
        for info in prepped.iter_mut() {
            info.prefix = scale;
        }
        for info in prepped.iter_mut() {
            let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
            info.peak = verts
                .iter()
                .map(|&v| deltas[v][0].hypot(deltas[v][1]))
                .fold(0.0, f64::max);
        }
    }
    let table = geometry::index_map(upstream);
    let mut candidate = upstream.to_vec();
    for &v in &var_verts {
        let Some(pos) = table.get(v).copied().flatten() else {
            continue;
        };
        for axis in 0..2 {
            if fixed.contains_key(&(v, axis)) {
                continue;
            }
            let value = upstream_coords[v][axis] + deltas[v][axis];
            if value == upstream_coords[v][axis] {
                continue;
            }
            let rounded = geometry::round_26_6(value) as f32;
            match &mut candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                }
                FittedCommand::QuadTo(x1, y1, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1);
                }
                FittedCommand::CurveTo(x1, y1, x2, y2, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1, x2, y2);
                }
                FittedCommand::Close => {}
            }
        }
    }
    let achieved_fallback = achieved_widths(&prepped, upstream);
    if candidate == upstream {
        let widths = mean_widths(&achieved_fallback);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "no-movement".to_string(),
            diagnostics: serde_json::json!({
                "validity": {"ok": true, "stage": "zero-change"},
                "pairs": achieved_json(&prepped, &achieved_fallback),
                "skipped": skipped_json,
                "phase_applied": false,
                "fixed": fixed_meta,
                "movement": 0.0,
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "grid": false,
                "widths": widths,
                "reference": reference_meta(reference),
            }),
        });
    }
    let validity = validate(
        &parsed,
        &fitted,
        upstream,
        &candidate,
        &portions,
        &mut prepped,
        &pins,
        &owned,
        source,
    );
    let mut validity = validity;
    if validity.ok {
        if let Err(reason) = geometry::curve_sweep_ok(
            &parsed,
            &fitted_coords,
            &candidate,
            &geometry::curve_controls(&fitted),
        ) {
            validity.ok = false;
            validity.stage = reason.to_string();
        }
    }
    let match_rows: Vec<(&Vec<f64>, f64)> = system
        .rows
        .iter()
        .filter(|(g, _, _)| *g == RowGroup::InkMatch)
        .map(|(_, row, constant)| (row, *constant))
        .collect();
    let flat_base_up: Vec<f64> = upstream_coords
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let cost_upstream: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_up.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cand_parsed =
        geometry::parse_commands(&candidate).map_err(|_| fail("unparseable-candidate"))?;
    let flat_base_cand: Vec<f64> = cand_parsed
        .oncurve
        .iter()
        .zip(base.iter())
        .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
        .collect();
    let cost_candidate: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_cand.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cost_ok = cost_candidate < cost_upstream;
    validity.cost_upstream = Some(cost_upstream);
    validity.cost_candidate = Some(cost_candidate);
    validity.cost_ok = cost_ok;
    if !cost_ok {
        validity.ok = false;
        validity.stage = "no-cost-decrease".to_string();
    }
    let achieved = achieved_widths(&prepped, &candidate);
    let widths = mean_widths(&achieved);
    if !validity.ok {
        let tried = mean_widths(&achieved);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "invalid-candidate".to_string(),
            diagnostics: serde_json::json!({
                "validity": validity_json(&validity),
                "pairs": achieved_json(&prepped, &achieved),
                "skipped": skipped_json,
                "phase_applied": false,
                "attempt": {
                    "movement": prepped.iter().map(|i| i.peak).fold(0.0, f64::max),
                    "widths": tried,
                    "pairs": achieved_json(&prepped, &achieved),

item.aggregated_output:
        let p: Vec<f64> = if zn == 0 {
            vec![0.0; n]
        } else {
            let res: Vec<f64> = b.iter().zip(ax.iter()).map(|(bi, ai)| bi - ai).collect();
            let y = system.reduced.solve(&DVector::from_vec(res));
            (0..n)
                .map(|i| (0..zn).map(|j| zmat[(i, j)] * y[j]).sum())
                .collect()
        };
        if !p.iter().all(|v| v.is_finite()) {
            return None;
        }
        if norm(&p) <= tol.primal {
            // Stationary on the working set: multiplier signs decide, under
            // L = f - λc with λ >= 0 on inequalities and box sides.
            let grads: Vec<(Vec<f64>, bool)> = active.iter().map(|w| w.grad_row(n)).collect();
            let wmat = if k == 0 {
                DMatrix::zeros(0, n)
            } else {
                let flat: Vec<f64> = grads.iter().flat_map(|(w, _)| w.iter().copied()).collect();
                DMatrix::from_row_slice(k, n, &flat)
            };
            let lambda = lstsq(&wmat.transpose(), &DVector::from_vec(d.clone()));
            let gl: Vec<f64> = (0..n)
                .map(|j| (0..k).map(|r| wmat[(r, j)] * lambda[r]).sum())
                .collect();
            let residual = norm(
                &d.iter()
                    .zip(gl.iter())
                    .map(|(a, b)| a - b)
                    .collect::<Vec<f64>>(),
            );
            let mut worst: Option<usize> = None;
            let mut worst_val = 0.0f64;
            for (r, (_, nonneg)) in grads.iter().enumerate() {
                if !nonneg {
                    continue;
                }
                if lambda[r] < worst_val {
                    worst_val = lambda[r];
                    worst = Some(r);
                }
            }
            let scale = 1.0 + dnorm;
            let dual_ok = worst_val >= -tol.dual * scale;
            if dual_ok && residual <= tol.stationarity * scale {
                let slack = ie
                    .iter()
                    .map(|(row, lower)| dot(row, &x) - lower)
                    .fold(f64::INFINITY, f64::min);
                let box_slack = x
                    .iter()
                    .zip(bounds.iter())
                    .map(|(v, limit)| limit - v.abs())
                    .fold(f64::INFINITY, f64::min);
                // Prototype delivery gate: a stationary point that still
                // violates a general inequality is infeasible, never a
                // result, even with a zero gradient.
                if slack < -DELIVER_SLACK {
                    return None;
                }
                if eq_error_max(&eq, &x) > tol.equality
                    || x.iter()
                        .zip(bounds.iter())
                        .any(|(v, limit)| v.abs() > limit + tol.primal)
                {
                    return None;
                }
                return Some((
                    x.clone(),
                    QpInfo {
                        iterations: iteration + 1,
                        equality_error: eq_error_max(&eq, &x),
                        stationarity_error: residual,
                        inequality_slack: slack.min(box_slack).min(0.0),
                        active: active.len(),
                    },
                ));
            }
            if let Some(r) = worst {
                if worst_val < -tol.dual * scale {
                    // Release the most negative bound multiplier and continue.
                    active.remove(r);
                    direction = None;
                    continue;
                }
            }
            return None;
        }
        // Step to the first blocking bound or inequality.
        let mut step = 1.0f64;
        let mut blocking: Option<WorkRow> = None;
        for (i, &pi) in p.iter().enumerate() {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Upper(j) | WorkRow::Lower(j) if *j == i))
            {
                continue;
            }
            if pi > tol.primal {
                let dist = (bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Upper(i));
                }
            } else if pi < -tol.primal {
                let dist = (-bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Lower(i));
                }
            }
        }
        for (row, lower) in ie {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Ineq(r, l) if r == row && l == lower))
            {
                continue;
            }
            let denom = dot(row, &p);
            if denom < -tol.primal {
                let dist = (lower - dot(row, &x)) / denom;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Ineq(row.clone(), *lower));
                }
            }
        }
        for (v, pi) in x.iter_mut().zip(p.iter()) {
            *v += step * pi;
        }
        // A recorded blocker was the strict minimum, so the step stops on
        // it; a full step leaves the working set unchanged.
        if let Some(work) = blocking {
            active.push(work);
            direction = None;
        }
    }
    None
}

fn eq_error_max(eq: &[(Vec<f64>, f64)], x: &[f64]) -> f64 {
    eq.iter()
        .map(|(row, h)| (dot(row, x) - h).abs())
        .fold(0.0_f64, f64::max)
}

/// Elastic Phase I: minimize t subject to Gx = h, Cx + t >= lower,
/// |x| <= bounds + t and t >= 0.
///
/// The auxiliary program has the known feasible start (x_eq, t0) with t0
/// the worst violation at the equality min-norm point, and its optimum is
/// t* = 0 exactly for feasible originals. It runs through the real
/// active-set core with release, so no row is ever frozen in: constraints
/// leave the working set by the same multiplier rule as the main solve.
/// Returns the repaired x when t* certifies feasibility; otherwise None,
/// which is the infeasible certificate the main solve would otherwise lack.
fn elastic_start(
    tol: &Tolerances,
    eq: &[(Vec<f64>, f64)],
    ie: &[(Vec<f64>, f64)],
    bounds: &[f64],
    x0: Vec<f64>,
) -> Option<Vec<f64>> {
    let n = x0.len();
    let mut t0 = 0.0f64;
    for (row, lower) in ie {
        t0 = t0.max(lower - dot(row, &x0));
    }
    for (v, limit) in x0.iter().zip(bounds.iter()) {
        t0 = t0.max(v.abs() - limit);
    }
    if !t0.is_finite() {
        return None;
    }
    let mut t_row = vec![0.0; n + 1];
    t_row[n] = 1.0;
    let eq_el: Vec<(Vec<f64>, f64)> = eq
        .iter()
        .map(|(w, h)| ([w.clone(), vec![0.0]].concat(), *h))
        .collect();
    let mut ie_el: Vec<(Vec<f64>, f64)> = Vec::with_capacity(ie.len() + 2 * n + 1);
    for (w, l) in ie {
        ie_el.push(([w.clone(), vec![1.0]].concat(), *l));
    }
    for (i, limit) in bounds.iter().enumerate() {
        let mut up = vec![0.0; n + 1];
        up[i] = -1.0;
        up[n] = 1.0;
        ie_el.push((up, -limit));
        let mut dn = vec![0.0; n + 1];
        dn[i] = 1.0;
        dn[n] = 1.0;
        ie_el.push((dn, -limit));
    }
    ie_el.push((t_row.clone(), 0.0));
    let eb: Vec<f64> = bounds
        .iter()
        .map(|l| l + t0 + 1e-6)
        .chain(std::iter::once(t0 + 1e-6))
        .collect();
    let mut start = x0;
    start.push(t0);
    let (xt, _) = solve_core(tol, &[t_row], &[0.0], &eq_el, &ie_el, &eb, start)?;
    // The handoff band admits near-zero slack only; delivery itself stays
    // gated on the prototype bands inside the main solve.
    if !(xt[n] <= 1e-7) {
        return None;
    }
    Some(xt[..n].to_vec())
}

/// Feasible primal active-set least squares with equality and box limits.
///
/// Native port of the joint-model `_bounded_equalities`: `a x = b` in the
/// least-squares sense subject to `g x = h` and `|x[i]| <= bounds[i]`.
/// Returns the displacement and solver evidence, or `None` when
/// initialization is infeasible or the iteration budget is exhausted.
pub(super) fn bounded_equalities(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    bounds: &[f64],
) -> Option<(Vec<f64>, QpInfo)> {
    active_set(
        &BOUNDED_TOL,
        a,
        b,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &[],
        bounds,
        true,
    )
}

/// Fixed convex least squares with linear constraints and box bounds.
///
/// Native port of the attached-model `_convex_qp`: minimizes
/// `1/2 |a x - b|^2` subject to `g x = h`, `c x >= lower` and
/// `|x| <= bound`. SciPy SLSQP supplies the prototype's numerical
/// candidate; this independent active-set implementation targets the same
/// constrained minimizer, gated by primal feasibility and the KKT
/// normal-cone check. Any rounding-level difference against an alternate
/// algorithm is diagnosed from these errors, never patched with offsets.
pub(super) fn convex_qp(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    c: &[Vec<f64>],
    lower: &[f64],
    bound: f64,
) -> Option<(Vec<f64>, QpInfo)> {
    let Some(n) = a
        .iter()
        .map(Vec::len)
        .chain(g.iter().map(Vec::len))
        .chain(c.iter().map(Vec::len))
        .max()
    else {
        return None;
    };
    // Prototype spectral normalization: the objective runs at
    // max(1, ||A||_2) so the SLSQP numerics and the KKT gates share one
    // scale. The minimizer is unchanged; the reported errors live in the
    // scaled system exactly as in the prototype.
    let scale = if a.is_empty() {
        1.0
    } else {
        let flat: Vec<f64> = a.iter().flat_map(|r| r.iter().copied()).collect();
        let normed = DMatrix::from_row_slice(a.len(), n, &flat);
        normed
            .svd(false, false)
            .singular_values
            .iter()
            .cloned()
            .fold(0.0_f64, f64::max)
            .max(1.0)
    };
    let a_scaled: Vec<Vec<f64>> = a
        .iter()
        .map(|r| r.iter().map(|v| v / scale).collect())
        .collect();
    let b_scaled: Vec<f64> = b.iter().map(|v| v / scale).collect();
    active_set(
        &CONVEX_TOL,
        &a_scaled,
        &b_scaled,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &c.iter()
            .zip(lower.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &vec![bound; n],
        false,
    )
}

// NIST Sparse BLAS matrix/vector and matrix/matrix operations:
// https://math.nist.gov/spblas/ . Exact-zero supports retain ascending
// accumulation order. Finite operands and nonzero finite results permit
// omitted zero products; otherwise the original dense dot retains signed
// zero, overflow and exceptional arithmetic. No approximate sparsity.
struct SparseObjective<'a> {
    dense: &'a [Vec<f64>],
    rows: Vec<Vec<(usize, f64)>>,
    }
    let mut ring = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) || var_verts.contains(&j) {
                ring.insert((i, j));
            }
        }
    }
    let mut ring_sorted: Vec<(usize, usize)> = ring.into_iter().collect();
    ring_sorted.sort();
    for (i, j) in ring_sorted {
        let _ = system.edge(i, j);
    }
    let base = parsed.oncurve.clone();
    let upstream = fitted_coords.to_vec();
    let shift: Vec<f64> = base
        .iter()
        .zip(upstream.iter())
        .flat_map(|(b, u)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for (group, row, constant) in system.rows.iter_mut() {
        match group {
            RowGroup::Position | RowGroup::Stretch | RowGroup::Bend => {
                let dot: f64 = row.iter().zip(shift.iter()).map(|(r, s)| r * s).sum();
                *constant -= dot;
            }
            RowGroup::InkMatch => {}
        }
    }
    for info in prepped.iter_mut() {
        let ta = |frac: f64| Sample::affine(info.a.i0, 1.0 - frac, info.a.i1, frac);
        let tb = |frac: f64| Sample::affine(info.b.i0, 1.0 - frac, info.b.i1, frac);
        let mut station_pairs = Vec::new();
        let mut ok = true;
        for st in &info.stations {
            let fa = info.a.t0 + (info.a.t1 - info.a.t0) * st.hit.sa;
            let fb = info.b.t0 + (info.b.t1 - info.b.t0) * st.hit.sb;
            match system.pair(&ta(fa), &tb(fb), info.arc, st.hit.center) {
                Ok(p) => station_pairs.push(p),
                Err(()) => {
                    ok = false;
                    break;
                }
            }
        }
        if !ok {
            continue;
        }
        info.pairs = Vec::with_capacity(station_pairs.len());
        for ((error, width, tangent), st) in station_pairs.into_iter().zip(info.stations.iter()) {
            info.pairs.push((error.clone(), width, tangent));
            for anchor in anchors {
                // Hobby (17) couples through the acute meeting angle: spine
                // order carries no orientation, so only the run side is
                // flipped toward the anchor; the reference stays unchanged.
                let run_tangent = acute(tangent, anchor.tangent);
                let psi = width_weight(
                    width,
                    anchor.source_width,
                    run_tangent,
                    anchor.tangent,
                    size_px,
                );
                let weight = info.arc * anchor.length * psi;
                let scaled: Vec<f64> = error.iter().map(|x| x * weight.sqrt()).collect();
                system
                    .rows
                    .push((RowGroup::InkMatch, scaled, anchor.rel * weight.sqrt()));
            }
            let _ = st;
        }
    }
    let mut fixed: HashMap<(usize, usize), f64> = HashMap::new();
    let gaps: Vec<[f64; 2]> = upstream
        .iter()
        .zip(base.iter())
        .map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for &v in pins {
        fixed.insert((v, 0), gaps[v][0]);
        fixed.insert((v, 1), gaps[v][1]);
    }
    for &v in &var_verts {
        for &axis in owned_axes {
            fixed.insert((v, axis), gaps[v][axis]);
        }
    }
    let mut far = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) && !var_verts.contains(&j) {
                far.insert(j);
            }
            if var_verts.contains(&j) && !var_verts.contains(&i) {
                far.insert(i);
            }
        }
    }
    for v in far {
        for axis in 0..2 {
            fixed.entry((v, axis)).or_insert(gaps[v][axis]);
        }
    }
    (system, fixed, var_verts)
}

/// Sorted vertex list for deterministic diagnostics; HashSet order is random.
fn sorted_verts(set: &HashSet<usize>) -> Vec<usize> {
    let mut out: Vec<usize> = set.iter().copied().collect();
    out.sort();
    out
}

fn abstain(upstream: &[FittedCommand], reason: &str, diagnostics: serde_json::Value) -> FitResult {
    FitResult {
        commands: upstream.to_vec(),
        applied: false,
        reason: reason.to_string(),
        diagnostics,
    }
}

/// Fit diagonal pairs of one glyph; exact upstream on abstention.
///
/// The joint system couples every diagonal station to every reference
/// anchor through (17) rows while source shape rows hold the outline;
/// shared vertices carry one unknown. Native-owned components and upright
/// anchors stay at upstream exactly. The candidate rounds moved coordinates
/// to 26.6 and must preserve orientation signs, upstream portion topology
/// and station ink, or the exact upstream commands return with the validity
/// evidence. Width-only: no grid arm, canonical exact crossings, interval
/// ownership.
pub fn fit(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    fit_with_analysis(
        source,
        upstream,
        size_px,
        reference,
        native_axes,
        &SourceAnalysis::new(source),
    )
}

pub(super) fn fit_with_analysis(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
    analysis: &SourceAnalysis<'_>,
) -> Result<FitResult, Error> {
    if !(size_px.is_finite() && size_px > 0.0) {
        return Err(fail("diagonal width requires finite positive size"));
    }
    if !geometry::check_correspondence(source, upstream) {
        return Ok(abstain(
            upstream,
            "no-correspondence",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (Ok(parsed), Ok(fitted)) = (analysis.parsed(), geometry::parse_commands(upstream)) else {
        return Ok(abstain(
            upstream,
            "malformed-commands",
            serde_json::json!({"size_px": size_px}),
        ));
    };
    if source.len() > MAX_COMMANDS || upstream.len() > MAX_COMMANDS {
        return Ok(abstain(
            upstream,
            "oversize-outline",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    if reference.anchors.is_empty() {
        return Ok(abstain(
            upstream,
            "no-reference-anchors",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (portions, curve_boxes, loops, flats) = analysis.visible();
    let (pairs, skipped) = analysis.pairs();
    let mut skipped = skipped.clone();
    let straights = loops.clone();
    let mut pins: HashSet<usize> = HashSet::new();
    for pair in geometry::upright_pairs(&pairs) {
        for side in [&pair.a, &pair.b] {
            pins.insert(side.i0);
            pins.insert(side.i1);
        }
    }
    for contour in &parsed.contours {
        for seg in contour {
            if seg.is_line() {
                continue;
            }
            let (a, b) = seg.endpoints();
            pins.insert(a);
            pins.insert(b);
        }
    }
    let owned: Vec<usize> = native_axes
        .iter()
        .enumerate()
        .filter(|(_, on)| **on)
        .map(|(axis, _)| axis)
        .collect();
    let borders = geometry::visible_borders(&portions);
    let fitted_coords = fitted.oncurve.clone();
    let mut prepped: Vec<PreppedInfo> = Vec::new();
    for pair in pairs {
        if geometry::upright_pairs(std::slice::from_ref(pair)).len() == 1 {
            skipped.push(geometry::Skipped {
                pair: (pair.a.seg, pair.b.seg),
                reason: "upright-anchor".to_string(),
            });
            continue;
        }
        match geometry::prepare_pair(
            pair,
            &borders,
            &loops,
            &straights,
            &flats,
            &curve_boxes,
            &fitted_coords,
            &geometry::curve_controls(&parsed),
        ) {
            Ok(prepped_pair) => {
                let bound = prepped_pair
                    .src_widths
                    .iter()
                    .cloned()
                    .fold(f64::INFINITY, f64::min)
                    / 2.0
                    - HEADROOM;
                if !(bound >= HEADROOM) {
                    skipped.push(geometry::Skipped {
                        pair: (pair.a.seg, pair.b.seg),
                        reason: "movement-budget-empty".to_string(),
                    });
                    continue;
                }
                let feet = serde_json::Value::Array(
                    pair.feet
                        .as_ref()
                        .map(|ranges| {
                            ranges
                                .iter()
                                .map(|r| serde_json::json!({"a": r.a, "b": r.b}))
                                .collect()
                        })
                        .unwrap_or_default(),
                );
                prepped.push(PreppedInfo {
                    id: prepped_pair.id,
                    a: prepped_pair.a,
                    b: prepped_pair.b,
                    normal: prepped_pair.normal,
                    stations: prepped_pair.stations,
                    src_widths: prepped_pair.src_widths,
                    fit_widths: prepped_pair.fit_widths,
                    arc: prepped_pair.arc,
                    span_lo: prepped_pair.span_lo,
                    span_hi: prepped_pair.span_hi,
                    bound,
                    prefix: 1.0,
                    peak: 0.0,
                    rounded_peak: None,
                    pairs: Vec::new(),
                    feet,
                });
            }
            Err(reason) => {
                skipped.push(geometry::Skipped {
                    pair: (pair.a.seg, pair.b.seg),
                    reason: reason.to_string(),
                });
            }
        }
    }
    let fixed_meta = serde_json::json!({
        "anchors": sorted_verts(&pins),
        "native_axes": [native_axes[0], native_axes[1]],
    });
    let skipped_json: Vec<serde_json::Value> = skipped
        .iter()
        .map(|s| serde_json::json!({"pair": [s.pair.0, s.pair.1], "reason": s.reason}))
        .collect();
    if prepped.is_empty() {
        return Ok(abstain(
            upstream,
            "all-abstained",
            serde_json::json!({"skipped": skipped_json, "fixed": fixed_meta}),
        ));
    }
    let (system, fixed, var_verts) = assemble(
        &parsed,
        &fitted_coords,
        &mut prepped,
        &reference.anchors,
        size_px,
        &pins,
        &owned,
    );
    let loose = solve_constrained(&system.rows, &fixed, parsed.oncurve.len());
    let base = parsed.oncurve.clone();
    let upstream_coords = fitted_coords.clone();
    let mut deltas: Vec<[f64; 2]> = (0..base.len())
        .map(|v| {
            [
                base[v][0] + loose[2 * v] - upstream_coords[v][0],
                base[v][1] + loose[2 * v + 1] - upstream_coords[v][1],
            ]
        })
        .collect();
    for info in prepped.iter_mut() {
        let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
        info.peak = verts
            .iter()
            .map(|&v| deltas[v][0].hypot(deltas[v][1]))
            .fold(0.0, f64::max);
    }
    let over: Vec<&PreppedInfo> = prepped
        .iter()
        .filter(|info| info.peak > info.bound)
        .collect();
    if !over.is_empty() {
        // Convex descent along the upstream-to-minimizer segment: the
        // objective decreases monotonically, so the feasible prefix keeps
        // every fixed coordinate exact while restoring the budget.
        let scale = over
            .iter()
            .map(|info| info.bound / info.peak)
            .fold(f64::INFINITY, f64::min);
        for d in deltas.iter_mut() {
            d[0] *= scale;
            d[1] *= scale;
        }
        for info in prepped.iter_mut() {
            info.prefix = scale;
        }
        for info in prepped.iter_mut() {
            let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
            info.peak = verts
                .iter()
                .map(|&v| deltas[v][0].hypot(deltas[v][1]))
                .fold(0.0, f64::max);
        }
    }
    let table = geometry::index_map(upstream);
    let mut candidate = upstream.to_vec();
    for &v in &var_verts {
        let Some(pos) = table.get(v).copied().flatten() else {
            continue;
        };
        for axis in 0..2 {
            if fixed.contains_key(&(v, axis)) {
                continue;
            }
            let value = upstream_coords[v][axis] + deltas[v][axis];
            if value == upstream_coords[v][axis] {
                continue;
            }
            let rounded = geometry::round_26_6(value) as f32;
            match &mut candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                }
                FittedCommand::QuadTo(x1, y1, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1);
                }
                FittedCommand::CurveTo(x1, y1, x2, y2, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1, x2, y2);
                }
                FittedCommand::Close => {}
            }
        }
    }
    let achieved_fallback = achieved_widths(&prepped, upstream);
    if candidate == upstream {
        let widths = mean_widths(&achieved_fallback);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "no-movement".to_string(),
            diagnostics: serde_json::json!({
                "validity": {"ok": true, "stage": "zero-change"},
                "pairs": achieved_json(&prepped, &achieved_fallback),
                "skipped": skipped_json,
                "phase_applied": false,
                "fixed": fixed_meta,
                "movement": 0.0,
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "grid": false,
                "widths": widths,
                "reference": reference_meta(reference),
            }),
        });
    }
    let validity = validate(
        &parsed,
        &fitted,
        upstream,
        &candidate,
        &portions,
        &mut prepped,
        &pins,
        &owned,
        source,
    );
    let mut validity = validity;
    if validity.ok {
        if let Err(reason) = geometry::curve_sweep_ok(
            &parsed,
            &fitted_coords,
            &candidate,
            &geometry::curve_controls(&fitted),
        ) {
            validity.ok = false;
            validity.stage = reason.to_string();
        }
    }
    let match_rows: Vec<(&Vec<f64>, f64)> = system
        .rows
        .iter()
        .filter(|(g, _, _)| *g == RowGroup::InkMatch)
        .map(|(_, row, constant)| (row, *constant))
        .collect();
    let flat_base_up: Vec<f64> = upstream_coords
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let cost_upstream: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_up.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cand_parsed =
        geometry::parse_commands(&candidate).map_err(|_| fail("unparseable-candidate"))?;
    let flat_base_cand: Vec<f64> = cand_parsed
        .oncurve
        .iter()
        .zip(base.iter())
        .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
        .collect();
    let cost_candidate: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_cand.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cost_ok = cost_candidate < cost_upstream;
    validity.cost_upstream = Some(cost_upstream);
    validity.cost_candidate = Some(cost_candidate);
    validity.cost_ok = cost_ok;
    if !cost_ok {
        validity.ok = false;
        validity.stage = "no-cost-decrease".to_string();
    }
    let achieved = achieved_widths(&prepped, &candidate);
    let widths = mean_widths(&achieved);
    if !validity.ok {
        let tried = mean_widths(&achieved);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "invalid-candidate".to_string(),
            diagnostics: serde_json::json!({
                "validity": validity_json(&validity),
                "pairs": achieved_json(&prepped, &achieved),
                "skipped": skipped_json,
                "phase_applied": false,
                "attempt": {
                    "movement": prepped.iter().map(|i| i.peak).fold(0.0, f64::max),
                    "widths": tried,
                    "pairs": achieved_json(&prepped, &achieved),

item.formatted_output:
        let p: Vec<f64> = if zn == 0 {
            vec![0.0; n]
        } else {
            let res: Vec<f64> = b.iter().zip(ax.iter()).map(|(bi, ai)| bi - ai).collect();
            let y = system.reduced.solve(&DVector::from_vec(res));
            (0..n)
                .map(|i| (0..zn).map(|j| zmat[(i, j)] * y[j]).sum())
                .collect()
        };
        if !p.iter().all(|v| v.is_finite()) {
            return None;
        }
        if norm(&p) <= tol.primal {
            // Stationary on the working set: multiplier signs decide, under
            // L = f - λc with λ >= 0 on inequalities and box sides.
            let grads: Vec<(Vec<f64>, bool)> = active.iter().map(|w| w.grad_row(n)).collect();
            let wmat = if k == 0 {
                DMatrix::zeros(0, n)
            } else {
                let flat: Vec<f64> = grads.iter().flat_map(|(w, _)| w.iter().copied()).collect();
                DMatrix::from_row_slice(k, n, &flat)
            };
            let lambda = lstsq(&wmat.transpose(), &DVector::from_vec(d.clone()));
            let gl: Vec<f64> = (0..n)
                .map(|j| (0..k).map(|r| wmat[(r, j)] * lambda[r]).sum())
                .collect();
            let residual = norm(
                &d.iter()
                    .zip(gl.iter())
                    .map(|(a, b)| a - b)
                    .collect::<Vec<f64>>(),
            );
            let mut worst: Option<usize> = None;
            let mut worst_val = 0.0f64;
            for (r, (_, nonneg)) in grads.iter().enumerate() {
                if !nonneg {
                    continue;
                }
                if lambda[r] < worst_val {
                    worst_val = lambda[r];
                    worst = Some(r);
                }
            }
            let scale = 1.0 + dnorm;
            let dual_ok = worst_val >= -tol.dual * scale;
            if dual_ok && residual <= tol.stationarity * scale {
                let slack = ie
                    .iter()
                    .map(|(row, lower)| dot(row, &x) - lower)
                    .fold(f64::INFINITY, f64::min);
                let box_slack = x
                    .iter()
                    .zip(bounds.iter())
                    .map(|(v, limit)| limit - v.abs())
                    .fold(f64::INFINITY, f64::min);
                // Prototype delivery gate: a stationary point that still
                // violates a general inequality is infeasible, never a
                // result, even with a zero gradient.
                if slack < -DELIVER_SLACK {
                    return None;
                }
                if eq_error_max(&eq, &x) > tol.equality
                    || x.iter()
                        .zip(bounds.iter())
                        .any(|(v, limit)| v.abs() > limit + tol.primal)
                {
                    return None;
                }
                return Some((
                    x.clone(),
                    QpInfo {
                        iterations: iteration + 1,
                        equality_error: eq_error_max(&eq, &x),
                        stationarity_error: residual,
                        inequality_slack: slack.min(box_slack).min(0.0),
                        active: active.len(),
                    },
                ));
            }
            if let Some(r) = worst {
                if worst_val < -tol.dual * scale {
                    // Release the most negative bound multiplier and continue.
                    active.remove(r);
                    direction = None;
                    continue;
                }
            }
            return None;
        }
        // Step to the first blocking bound or inequality.
        let mut step = 1.0f64;
        let mut blocking: Option<WorkRow> = None;
        for (i, &pi) in p.iter().enumerate() {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Upper(j) | WorkRow::Lower(j) if *j == i))
            {
                continue;
            }
            if pi > tol.primal {
                let dist = (bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Upper(i));
                }
            } else if pi < -tol.primal {
                let dist = (-bounds[i] - x[i]) / pi;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Lower(i));
                }
            }
        }
        for (row, lower) in ie {
            if active
                .iter()
                .any(|w| matches!(w, WorkRow::Ineq(r, l) if r == row && l == lower))
            {
                continue;
            }
            let denom = dot(row, &p);
            if denom < -tol.primal {
                let dist = (lower - dot(row, &x)) / denom;
                if dist < step {
                    step = dist.max(0.0);
                    blocking = Some(WorkRow::Ineq(row.clone(), *lower));
                }
            }
        }
        for (v, pi) in x.iter_mut().zip(p.iter()) {
            *v += step * pi;
        }
        // A recorded blocker was the strict minimum, so the step stops on
        // it; a full step leaves the working set unchanged.
        if let Some(work) = blocking {
            active.push(work);
            direction = None;
        }
    }
    None
}

fn eq_error_max(eq: &[(Vec<f64>, f64)], x: &[f64]) -> f64 {
    eq.iter()
        .map(|(row, h)| (dot(row, x) - h).abs())
        .fold(0.0_f64, f64::max)
}

/// Elastic Phase I: minimize t subject to Gx = h, Cx + t >= lower,
/// |x| <= bounds + t and t >= 0.
///
/// The auxiliary program has the known feasible start (x_eq, t0) with t0
/// the worst violation at the equality min-norm point, and its optimum is
/// t* = 0 exactly for feasible originals. It runs through the real
/// active-set core with release, so no row is ever frozen in: constraints
/// leave the working set by the same multiplier rule as the main solve.
/// Returns the repaired x when t* certifies feasibility; otherwise None,
/// which is the infeasible certificate the main solve would otherwise lack.
fn elastic_start(
    tol: &Tolerances,
    eq: &[(Vec<f64>, f64)],
    ie: &[(Vec<f64>, f64)],
    bounds: &[f64],
    x0: Vec<f64>,
) -> Option<Vec<f64>> {
    let n = x0.len();
    let mut t0 = 0.0f64;
    for (row, lower) in ie {
        t0 = t0.max(lower - dot(row, &x0));
    }
    for (v, limit) in x0.iter().zip(bounds.iter()) {
        t0 = t0.max(v.abs() - limit);
    }
    if !t0.is_finite() {
        return None;
    }
    let mut t_row = vec![0.0; n + 1];
    t_row[n] = 1.0;
    let eq_el: Vec<(Vec<f64>, f64)> = eq
        .iter()
        .map(|(w, h)| ([w.clone(), vec![0.0]].concat(), *h))
        .collect();
    let mut ie_el: Vec<(Vec<f64>, f64)> = Vec::with_capacity(ie.len() + 2 * n + 1);
    for (w, l) in ie {
        ie_el.push(([w.clone(), vec![1.0]].concat(), *l));
    }
    for (i, limit) in bounds.iter().enumerate() {
        let mut up = vec![0.0; n + 1];
        up[i] = -1.0;
        up[n] = 1.0;
        ie_el.push((up, -limit));
        let mut dn = vec![0.0; n + 1];
        dn[i] = 1.0;
        dn[n] = 1.0;
        ie_el.push((dn, -limit));
    }
    ie_el.push((t_row.clone(), 0.0));
    let eb: Vec<f64> = bounds
        .iter()
        .map(|l| l + t0 + 1e-6)
        .chain(std::iter::once(t0 + 1e-6))
        .collect();
    let mut start = x0;
    start.push(t0);
    let (xt, _) = solve_core(tol, &[t_row], &[0.0], &eq_el, &ie_el, &eb, start)?;
    // The handoff band admits near-zero slack only; delivery itself stays
    // gated on the prototype bands inside the main solve.
    if !(xt[n] <= 1e-7) {
        return None;
    }
    Some(xt[..n].to_vec())
}

/// Feasible primal active-set least squares with equality and box limits.
///
/// Native port of the joint-model `_bounded_equalities`: `a x = b` in the
/// least-squares sense subject to `g x = h` and `|x[i]| <= bounds[i]`.
/// Returns the displacement and solver evidence, or `None` when
/// initialization is infeasible or the iteration budget is exhausted.
pub(super) fn bounded_equalities(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    bounds: &[f64],
) -> Option<(Vec<f64>, QpInfo)> {
    active_set(
        &BOUNDED_TOL,
        a,
        b,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &[],
        bounds,
        true,
    )
}

/// Fixed convex least squares with linear constraints and box bounds.
///
/// Native port of the attached-model `_convex_qp`: minimizes
/// `1/2 |a x - b|^2` subject to `g x = h`, `c x >= lower` and
/// `|x| <= bound`. SciPy SLSQP supplies the prototype's numerical
/// candidate; this independent active-set implementation targets the same
/// constrained minimizer, gated by primal feasibility and the KKT
/// normal-cone check. Any rounding-level difference against an alternate
/// algorithm is diagnosed from these errors, never patched with offsets.
pub(super) fn convex_qp(
    a: &[Vec<f64>],
    b: &[f64],
    g: &[Vec<f64>],
    h: &[f64],
    c: &[Vec<f64>],
    lower: &[f64],
    bound: f64,
) -> Option<(Vec<f64>, QpInfo)> {
    let Some(n) = a
        .iter()
        .map(Vec::len)
        .chain(g.iter().map(Vec::len))
        .chain(c.iter().map(Vec::len))
        .max()
    else {
        return None;
    };
    // Prototype spectral normalization: the objective runs at
    // max(1, ||A||_2) so the SLSQP numerics and the KKT gates share one
    // scale. The minimizer is unchanged; the reported errors live in the
    // scaled system exactly as in the prototype.
    let scale = if a.is_empty() {
        1.0
    } else {
        let flat: Vec<f64> = a.iter().flat_map(|r| r.iter().copied()).collect();
        let normed = DMatrix::from_row_slice(a.len(), n, &flat);
        normed
            .svd(false, false)
            .singular_values
            .iter()
            .cloned()
            .fold(0.0_f64, f64::max)
            .max(1.0)
    };
    let a_scaled: Vec<Vec<f64>> = a
        .iter()
        .map(|r| r.iter().map(|v| v / scale).collect())
        .collect();
    let b_scaled: Vec<f64> = b.iter().map(|v| v / scale).collect();
    active_set(
        &CONVEX_TOL,
        &a_scaled,
        &b_scaled,
        &g.iter()
            .zip(h.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &c.iter()
            .zip(lower.iter())
            .map(|(r, v)| (r.clone(), *v))
            .collect::<Vec<_>>(),
        &vec![bound; n],
        false,
    )
}

// NIST Sparse BLAS matrix/vector and matrix/matrix operations:
// https://math.nist.gov/spblas/ . Exact-zero supports retain ascending
// accumulation order. Finite operands and nonzero finite results permit
// omitted zero products; otherwise the original dense dot retains signed
// zero, overflow and exceptional arithmetic. No approximate sparsity.
struct SparseObjective<'a> {
    dense: &'a [Vec<f64>],
    rows: Vec<Vec<(usize, f64)>>,
    }
    let mut ring = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) || var_verts.contains(&j) {
                ring.insert((i, j));
            }
        }
    }
    let mut ring_sorted: Vec<(usize, usize)> = ring.into_iter().collect();
    ring_sorted.sort();
    for (i, j) in ring_sorted {
        let _ = system.edge(i, j);
    }
    let base = parsed.oncurve.clone();
    let upstream = fitted_coords.to_vec();
    let shift: Vec<f64> = base
        .iter()
        .zip(upstream.iter())
        .flat_map(|(b, u)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for (group, row, constant) in system.rows.iter_mut() {
        match group {
            RowGroup::Position | RowGroup::Stretch | RowGroup::Bend => {
                let dot: f64 = row.iter().zip(shift.iter()).map(|(r, s)| r * s).sum();
                *constant -= dot;
            }
            RowGroup::InkMatch => {}
        }
    }
    for info in prepped.iter_mut() {
        let ta = |frac: f64| Sample::affine(info.a.i0, 1.0 - frac, info.a.i1, frac);
        let tb = |frac: f64| Sample::affine(info.b.i0, 1.0 - frac, info.b.i1, frac);
        let mut station_pairs = Vec::new();
        let mut ok = true;
        for st in &info.stations {
            let fa = info.a.t0 + (info.a.t1 - info.a.t0) * st.hit.sa;
            let fb = info.b.t0 + (info.b.t1 - info.b.t0) * st.hit.sb;
            match system.pair(&ta(fa), &tb(fb), info.arc, st.hit.center) {
                Ok(p) => station_pairs.push(p),
                Err(()) => {
                    ok = false;
                    break;
                }
            }
        }
        if !ok {
            continue;
        }
        info.pairs = Vec::with_capacity(station_pairs.len());
        for ((error, width, tangent), st) in station_pairs.into_iter().zip(info.stations.iter()) {
            info.pairs.push((error.clone(), width, tangent));
            for anchor in anchors {
                // Hobby (17) couples through the acute meeting angle: spine
                // order carries no orientation, so only the run side is
                // flipped toward the anchor; the reference stays unchanged.
                let run_tangent = acute(tangent, anchor.tangent);
                let psi = width_weight(
                    width,
                    anchor.source_width,
                    run_tangent,
                    anchor.tangent,
                    size_px,
                );
                let weight = info.arc * anchor.length * psi;
                let scaled: Vec<f64> = error.iter().map(|x| x * weight.sqrt()).collect();
                system
                    .rows
                    .push((RowGroup::InkMatch, scaled, anchor.rel * weight.sqrt()));
            }
            let _ = st;
        }
    }
    let mut fixed: HashMap<(usize, usize), f64> = HashMap::new();
    let gaps: Vec<[f64; 2]> = upstream
        .iter()
        .zip(base.iter())
        .map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    for &v in pins {
        fixed.insert((v, 0), gaps[v][0]);
        fixed.insert((v, 1), gaps[v][1]);
    }
    for &v in &var_verts {
        for &axis in owned_axes {
            fixed.insert((v, axis), gaps[v][axis]);
        }
    }
    let mut far = HashSet::new();
    for contour in &parsed.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i, j) = seg.endpoints();
            if var_verts.contains(&i) && !var_verts.contains(&j) {
                far.insert(j);
            }
            if var_verts.contains(&j) && !var_verts.contains(&i) {
                far.insert(i);
            }
        }
    }
    for v in far {
        for axis in 0..2 {
            fixed.entry((v, axis)).or_insert(gaps[v][axis]);
        }
    }
    (system, fixed, var_verts)
}

/// Sorted vertex list for deterministic diagnostics; HashSet order is random.
fn sorted_verts(set: &HashSet<usize>) -> Vec<usize> {
    let mut out: Vec<usize> = set.iter().copied().collect();
    out.sort();
    out
}

fn abstain(upstream: &[FittedCommand], reason: &str, diagnostics: serde_json::Value) -> FitResult {
    FitResult {
        commands: upstream.to_vec(),
        applied: false,
        reason: reason.to_string(),
        diagnostics,
    }
}

/// Fit diagonal pairs of one glyph; exact upstream on abstention.
///
/// The joint system couples every diagonal station to every reference
/// anchor through (17) rows while source shape rows hold the outline;
/// shared vertices carry one unknown. Native-owned components and upright
/// anchors stay at upstream exactly. The candidate rounds moved coordinates
/// to 26.6 and must preserve orientation signs, upstream portion topology
/// and station ink, or the exact upstream commands return with the validity
/// evidence. Width-only: no grid arm, canonical exact crossings, interval
/// ownership.
pub fn fit(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    fit_with_analysis(
        source,
        upstream,
        size_px,
        reference,
        native_axes,
        &SourceAnalysis::new(source),
    )
}

pub(super) fn fit_with_analysis(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
    analysis: &SourceAnalysis<'_>,
) -> Result<FitResult, Error> {
    if !(size_px.is_finite() && size_px > 0.0) {
        return Err(fail("diagonal width requires finite positive size"));
    }
    if !geometry::check_correspondence(source, upstream) {
        return Ok(abstain(
            upstream,
            "no-correspondence",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (Ok(parsed), Ok(fitted)) = (analysis.parsed(), geometry::parse_commands(upstream)) else {
        return Ok(abstain(
            upstream,
            "malformed-commands",
            serde_json::json!({"size_px": size_px}),
        ));
    };
    if source.len() > MAX_COMMANDS || upstream.len() > MAX_COMMANDS {
        return Ok(abstain(
            upstream,
            "oversize-outline",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    if reference.anchors.is_empty() {
        return Ok(abstain(
            upstream,
            "no-reference-anchors",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (portions, curve_boxes, loops, flats) = analysis.visible();
    let (pairs, skipped) = analysis.pairs();
    let mut skipped = skipped.clone();
    let straights = loops.clone();
    let mut pins: HashSet<usize> = HashSet::new();
    for pair in geometry::upright_pairs(&pairs) {
        for side in [&pair.a, &pair.b] {
            pins.insert(side.i0);
            pins.insert(side.i1);
        }
    }
    for contour in &parsed.contours {
        for seg in contour {
            if seg.is_line() {
                continue;
            }
            let (a, b) = seg.endpoints();
            pins.insert(a);
            pins.insert(b);
        }
    }
    let owned: Vec<usize> = native_axes
        .iter()
        .enumerate()
        .filter(|(_, on)| **on)
        .map(|(axis, _)| axis)
        .collect();
    let borders = geometry::visible_borders(&portions);
    let fitted_coords = fitted.oncurve.clone();
    let mut prepped: Vec<PreppedInfo> = Vec::new();
    for pair in pairs {
        if geometry::upright_pairs(std::slice::from_ref(pair)).len() == 1 {
            skipped.push(geometry::Skipped {
                pair: (pair.a.seg, pair.b.seg),
                reason: "upright-anchor".to_string(),
            });
            continue;
        }
        match geometry::prepare_pair(
            pair,
            &borders,
            &loops,
            &straights,
            &flats,
            &curve_boxes,
            &fitted_coords,
            &geometry::curve_controls(&parsed),
        ) {
            Ok(prepped_pair) => {
                let bound = prepped_pair
                    .src_widths
                    .iter()
                    .cloned()
                    .fold(f64::INFINITY, f64::min)
                    / 2.0
                    - HEADROOM;
                if !(bound >= HEADROOM) {
                    skipped.push(geometry::Skipped {
                        pair: (pair.a.seg, pair.b.seg),
                        reason: "movement-budget-empty".to_string(),
                    });
                    continue;
                }
                let feet = serde_json::Value::Array(
                    pair.feet
                        .as_ref()
                        .map(|ranges| {
                            ranges
                                .iter()
                                .map(|r| serde_json::json!({"a": r.a, "b": r.b}))
                                .collect()
                        })
                        .unwrap_or_default(),
                );
                prepped.push(PreppedInfo {
                    id: prepped_pair.id,
                    a: prepped_pair.a,
                    b: prepped_pair.b,
                    normal: prepped_pair.normal,
                    stations: prepped_pair.stations,
                    src_widths: prepped_pair.src_widths,
                    fit_widths: prepped_pair.fit_widths,
                    arc: prepped_pair.arc,
                    span_lo: prepped_pair.span_lo,
                    span_hi: prepped_pair.span_hi,
                    bound,
                    prefix: 1.0,
                    peak: 0.0,
                    rounded_peak: None,
                    pairs: Vec::new(),
                    feet,
                });
