/// anchors stay at upstream exactly. The candidate rounds moved coordinates
/// to 26.6 and must preserve orientation signs, upstream portion topology
/// and station ink, or the exact upstream commands return with the validity
/// evidence. Width-only: no grid arm, canonical exact crossings, interval
/// ownership.
pub fn fit(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
) -> Result<FitResult, Error> {
    fit_with_analysis(
        source,
        upstream,
        size_px,
        reference,
        native_axes,
        &SourceAnalysis::new(source),
    )
}

pub(super) fn fit_with_analysis(
    source: &[FittedCommand],
    upstream: &[FittedCommand],
    size_px: f64,
    reference: &Reference,
    native_axes: [bool; 2],
    analysis: &SourceAnalysis<'_>,
) -> Result<FitResult, Error> {
    if !(size_px.is_finite() && size_px > 0.0) {
        return Err(fail("diagonal width requires finite positive size"));
    }
    if !geometry::check_correspondence(source, upstream) {
        return Ok(abstain(
            upstream,
            "no-correspondence",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (Ok(parsed), Ok(fitted)) = (analysis.parsed(), geometry::parse_commands(upstream)) else {
        return Ok(abstain(
            upstream,
            "malformed-commands",
            serde_json::json!({"size_px": size_px}),
        ));
    };
    if source.len() > MAX_COMMANDS || upstream.len() > MAX_COMMANDS {
        return Ok(abstain(
            upstream,
            "oversize-outline",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    if reference.anchors.is_empty() {
        return Ok(abstain(
            upstream,
            "no-reference-anchors",
            serde_json::json!({"size_px": size_px}),
        ));
    }
    let (portions, curve_boxes, loops, flats) = analysis.visible();
    let (pairs, skipped) = analysis.pairs();
    let mut skipped = skipped.clone();
    let straights = loops.clone();
    let mut pins: HashSet<usize> = HashSet::new();
    for pair in geometry::upright_pairs(&pairs) {
        for side in [&pair.a, &pair.b] {
            pins.insert(side.i0);
            pins.insert(side.i1);
        }
    }
    for contour in &parsed.contours {
        for seg in contour {
            if seg.is_line() {
                continue;
            }
            let (a, b) = seg.endpoints();
            pins.insert(a);
            pins.insert(b);
        }
    }
    let owned: Vec<usize> = native_axes
        .iter()
        .enumerate()
        .filter(|(_, on)| **on)
        .map(|(axis, _)| axis)
        .collect();
    let borders = geometry::visible_borders(&portions);
    let fitted_coords = fitted.oncurve.clone();
    let mut prepped: Vec<PreppedInfo> = Vec::new();
    for pair in pairs {
        if geometry::upright_pairs(std::slice::from_ref(pair)).len() == 1 {
            skipped.push(geometry::Skipped {
                pair: (pair.a.seg, pair.b.seg),
                reason: "upright-anchor".to_string(),
            });
            continue;
        }
        match geometry::prepare_pair(
            pair,
            &borders,
            &loops,
            &straights,
            &flats,
            &curve_boxes,
            &fitted_coords,
            &geometry::curve_controls(&parsed),
        ) {
            Ok(prepped_pair) => {
                let bound = prepped_pair
                    .src_widths
                    .iter()
                    .cloned()
                    .fold(f64::INFINITY, f64::min)
                    / 2.0
                    - HEADROOM;
                if !(bound >= HEADROOM) {
                    skipped.push(geometry::Skipped {
                        pair: (pair.a.seg, pair.b.seg),
                        reason: "movement-budget-empty".to_string(),
                    });
                    continue;
                }
                let feet = serde_json::Value::Array(
                    pair.feet
                        .as_ref()
                        .map(|ranges| {
                            ranges
                                .iter()
                                .map(|r| serde_json::json!({"a": r.a, "b": r.b}))
                                .collect()
                        })
                        .unwrap_or_default(),
                );
                prepped.push(PreppedInfo {
                    id: prepped_pair.id,
                    a: prepped_pair.a,
                    b: prepped_pair.b,
                    normal: prepped_pair.normal,
                    stations: prepped_pair.stations,
                    src_widths: prepped_pair.src_widths,
                    fit_widths: prepped_pair.fit_widths,
                    arc: prepped_pair.arc,
                    span_lo: prepped_pair.span_lo,
                    span_hi: prepped_pair.span_hi,
                    bound,
                    prefix: 1.0,
                    peak: 0.0,
                    rounded_peak: None,
                    pairs: Vec::new(),
                    feet,
                });
            }
            Err(reason) => {
                skipped.push(geometry::Skipped {
                    pair: (pair.a.seg, pair.b.seg),
                    reason: reason.to_string(),
                });
            }
        }
    }
    let fixed_meta = serde_json::json!({
        "anchors": sorted_verts(&pins),
        "native_axes": [native_axes[0], native_axes[1]],
    });
    let skipped_json: Vec<serde_json::Value> = skipped
        .iter()
        .map(|s| serde_json::json!({"pair": [s.pair.0, s.pair.1], "reason": s.reason}))
        .collect();
    if prepped.is_empty() {
        return Ok(abstain(
            upstream,
            "all-abstained",
            serde_json::json!({"skipped": skipped_json, "fixed": fixed_meta}),
        ));
    }
    let (system, fixed, var_verts) = assemble(
        &parsed,
        &fitted_coords,
        &mut prepped,
        &reference.anchors,
        size_px,
        &pins,
        &owned,
    );
    let loose = solve_constrained(&system.rows, &fixed, parsed.oncurve.len());
    let base = parsed.oncurve.clone();
    let upstream_coords = fitted_coords.clone();
    let mut deltas: Vec<[f64; 2]> = (0..base.len())
        .map(|v| {
            [
                base[v][0] + loose[2 * v] - upstream_coords[v][0],
                base[v][1] + loose[2 * v + 1] - upstream_coords[v][1],
            ]
        })
        .collect();
    for info in prepped.iter_mut() {
        let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
        info.peak = verts
            .iter()
            .map(|&v| deltas[v][0].hypot(deltas[v][1]))
            .fold(0.0, f64::max);
    }
    let over: Vec<&PreppedInfo> = prepped
        .iter()
        .filter(|info| info.peak > info.bound)
        .collect();
    if !over.is_empty() {
        // Convex descent along the upstream-to-minimizer segment: the
        // objective decreases monotonically, so the feasible prefix keeps
        // every fixed coordinate exact while restoring the budget.
        let scale = over
            .iter()
            .map(|info| info.bound / info.peak)
            .fold(f64::INFINITY, f64::min);
        for d in deltas.iter_mut() {
            d[0] *= scale;
            d[1] *= scale;
        }
        for info in prepped.iter_mut() {
            info.prefix = scale;
        }
        for info in prepped.iter_mut() {
            let verts = [info.a.i0, info.a.i1, info.b.i0, info.b.i1];
            info.peak = verts
                .iter()
                .map(|&v| deltas[v][0].hypot(deltas[v][1]))
                .fold(0.0, f64::max);
        }
    }
    let table = geometry::index_map(upstream);
    let mut candidate = upstream.to_vec();
    for &v in &var_verts {
        let Some(pos) = table.get(v).copied().flatten() else {
            continue;
        };
        for axis in 0..2 {
            if fixed.contains_key(&(v, axis)) {
                continue;
            }
            let value = upstream_coords[v][axis] + deltas[v][axis];
            if value == upstream_coords[v][axis] {
                continue;
            }
            let rounded = geometry::round_26_6(value) as f32;
            match &mut candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                }
                FittedCommand::QuadTo(x1, y1, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1);
                }
                FittedCommand::CurveTo(x1, y1, x2, y2, x, y) => {
                    if axis == 0 {
                        *x = rounded;
                    } else {
                        *y = rounded;
                    }
                    let _ = (x1, y1, x2, y2);
                }
                FittedCommand::Close => {}
            }
        }
    }
    let achieved_fallback = achieved_widths(&prepped, upstream);
    if candidate == upstream {
        let widths = mean_widths(&achieved_fallback);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "no-movement".to_string(),
            diagnostics: serde_json::json!({
                "validity": {"ok": true, "stage": "zero-change"},
                "pairs": achieved_json(&prepped, &achieved_fallback),
                "skipped": skipped_json,
                "phase_applied": false,
                "fixed": fixed_meta,
                "movement": 0.0,
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "grid": false,
                "widths": widths,
                "reference": reference_meta(reference),
            }),
        });
    }
    let validity = validate(
        &parsed,
        &fitted,
        upstream,
        &candidate,
        &portions,
        &mut prepped,
        &pins,
        &owned,
        source,
    );
    let mut validity = validity;
    if validity.ok {
        if let Err(reason) = geometry::curve_sweep_ok(
            &parsed,
            &fitted_coords,
            &candidate,
            &geometry::curve_controls(&fitted),
        ) {
            validity.ok = false;
            validity.stage = reason.to_string();
        }
    }
    let match_rows: Vec<(&Vec<f64>, f64)> = system
        .rows
        .iter()
        .filter(|(g, _, _)| *g == RowGroup::InkMatch)
        .map(|(_, row, constant)| (row, *constant))
        .collect();
    let flat_base_up: Vec<f64> = upstream_coords
        .iter()
        .zip(base.iter())
        .flat_map(|(u, b)| [u[0] - b[0], u[1] - b[1]])
        .collect();
    let cost_upstream: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_up.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cand_parsed =
        geometry::parse_commands(&candidate).map_err(|_| fail("unparseable-candidate"))?;
    let flat_base_cand: Vec<f64> = cand_parsed
        .oncurve
        .iter()
        .zip(base.iter())
        .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
        .collect();
    let cost_candidate: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_cand.iter())
                .map(|(r, s)| r * s)
                .sum();
            (dot + constant).powi(2)
        })
        .sum();
    let cost_ok = cost_candidate < cost_upstream;
    validity.cost_upstream = Some(cost_upstream);
    validity.cost_candidate = Some(cost_candidate);
    validity.cost_ok = cost_ok;
    if !cost_ok {
        validity.ok = false;
        validity.stage = "no-cost-decrease".to_string();
    }
    let achieved = achieved_widths(&prepped, &candidate);
    let widths = mean_widths(&achieved);
    if !validity.ok {
        let tried = mean_widths(&achieved);
        return Ok(FitResult {
            commands: upstream.to_vec(),
            applied: false,
            reason: "invalid-candidate".to_string(),
            diagnostics: serde_json::json!({
                "validity": validity_json(&validity),
                "pairs": achieved_json(&prepped, &achieved),
                "skipped": skipped_json,
                "phase_applied": false,
                "attempt": {
                    "movement": prepped.iter().map(|i| i.peak).fold(0.0, f64::max),
                    "widths": tried,
                    "pairs": achieved_json(&prepped, &achieved),
"}

item.stdout:
                    "validity": validity_json(&validity),
                },
                "fixed": fixed_meta,
                "movement": 0.0,
                "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
                "size_px": size_px,
                "grid": false,
                "widths": mean_widths(&achieved_fallback),
                "reference": reference_meta(reference),
            }),
        });
    }
    Ok(FitResult {
        commands: candidate,
        applied: true,
        reason: "applied".to_string(),
        diagnostics: serde_json::json!({
            "validity": validity_json(&validity),
            "pairs": achieved_json(&prepped, &achieved),
            "skipped": skipped_json,
            "phase_applied": false,
            "fixed": fixed_meta,
            "movement": prepped.iter().map(|i| i.peak).fold(0.0, f64::max),
            "bound": prepped.iter().map(|i| i.bound).fold(f64::INFINITY, f64::min),
            "size_px": size_px,
            "grid": false,
            "widths": widths,
            "reference": reference_meta(reference),
        }),
    })
}

/// Post-rounding gates; any failure rejects the whole glyph.
struct Validity {
    ok: bool,
    stage: String,
    split_topology: bool,
    pins_exact: bool,
    centers_inked: bool,
    movement_ok: bool,
    cost_upstream: Option<f64>,
    cost_candidate: Option<f64>,
    cost_ok: bool,
}

fn validity_json(v: &Validity) -> serde_json::Value {
    serde_json::json!({
        "ok": v.ok,
        "stage": v.stage,
        "ops": true,
        "orientation": true,
        "split_topology": v.split_topology,
        "topology_mode": "exact_arrangement",
        "pins_exact": v.pins_exact,
        "centers_inked": v.centers_inked,
        "movement_ok": v.movement_ok,
        "hard_rounded_ok": true,
        "cost_upstream": v.cost_upstream,
        "cost_candidate": v.cost_candidate,
        "cost_ok": v.cost_ok,
    })
}

#[allow(clippy::too_many_arguments)]
fn validate(
    parsed: &Parsed,
    fitted: &Parsed,
    fitted_commands: &[FittedCommand],
    candidate: &[FittedCommand],
    portions: &[geometry::Portion],
    prepped: &mut [PreppedInfo],
    pins: &HashSet<usize>,
    owned: &[usize],
    source_commands: &[FittedCommand],
) -> Validity {
    let mut v = Validity {
        ok: true,
        stage: String::new(),
        split_topology: false,
        pins_exact: true,
        centers_inked: true,
        movement_ok: true,
        cost_upstream: None,
        cost_candidate: None,
        cost_ok: false,
    };
    if !geometry::check_correspondence(fitted_commands, candidate) {
        v.ok = false;
        v.stage = "ops-changed".to_string();
        return v;
    }
    let cand = match geometry::parse_commands(candidate) {
        Ok(c) => c,
        Err(()) => {
            v.ok = false;
            v.stage = "unparseable-candidate".to_string();
            return v;
        }
    };
    let before = geometry::signed_areas(&geometry::loops_points(fitted));
    let after = geometry::signed_areas(&geometry::loops_points(&cand));
    let orientation = before
        .iter()
        .zip(after.iter())
        .all(|(a, b)| a.signum() == b.signum());
    if !orientation {
        v.ok = false;
        v.stage = "orientation-flip".to_string();
        return v;
    }
    let (cand_portions, _, _, cand_flats) = geometry::split_visible(&cand, true);
    let (up_portions, _, _, up_flats) = geometry::split_visible(fitted, true);
    v.split_topology =
        geometry::topology_signature(&cand_portions) == geometry::topology_signature(&up_portions);
    let _ = portions;
    // Width-only adoption replaces the split gate with the exact arrangement
    // reference; ownership, correspondence, movement and ink checks stay.
    if !curves::compare_commands(source_commands, fitted_commands, candidate) {
        v.ok = false;
        v.stage = "topology-mismatch".to_string();
        return v;
    }
    let table = geometry::index_map(candidate);
    for &pin in pins {
        let Some(pos) = table.get(pin).copied().flatten() else {
            continue;
        };
        let (cx, cy) = match &candidate[pos] {
            FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => (*x as f64, *y as f64),
            FittedCommand::QuadTo(_, _, x, y) | FittedCommand::CurveTo(_, _, _, _, x, y) => {
                (*x as f64, *y as f64)
            }
            FittedCommand::Close => continue,
        };
        if cx != fitted.oncurve[pin][0] || cy != fitted.oncurve[pin][1] {
            v.pins_exact = false;
        }
    }
    let mut inverted: HashMap<usize, usize> = HashMap::new();
    for (idx, pos) in table.iter().enumerate() {
        if let Some(p) = pos {
            inverted.insert(*p, idx);
        }
    }
    for (pos, cmd) in candidate.iter().enumerate() {
        let Some(&idx) = inverted.get(&pos) else {
            continue;
        };
        for &axis in owned {
            let (cx, cy) = match cmd {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => (*x as f64, *y as f64),
                FittedCommand::QuadTo(_, _, x, y) | FittedCommand::CurveTo(_, _, _, _, x, y) => {
                    (*x as f64, *y as f64)
                }
                FittedCommand::Close => continue,
            };
            let want = fitted.oncurve[idx][axis];
            if (axis == 0 && cx != want) || (axis == 1 && cy != want) {
                v.pins_exact = false;
            }
        }
        let _ = parsed;
    }
    if !v.pins_exact {
        v.ok = false;
        v.stage = "pins-moved".to_string();
        return v;
    }
    let cand_loops = geometry::loops_points(&cand);
    let up_loops = geometry::loops_points(fitted);
    for info in prepped.iter_mut() {
        let mid = &info.stations[info.stations.len() / 2].hit;
        let qa = geometry::edge_point(&info.a, mid.sa, &cand.oncurve);
        let qb = geometry::edge_point(&info.b, mid.sb, &cand.oncurve);
        let center = [(qa[0] + qb[0]) / 2.0, (qa[1] + qb[1]) / 2.0];
        let wc = geometry::certified_winding(center, &cand_loops, &cand_flats);
        let ua = geometry::edge_point(&info.a, mid.sa, &fitted.oncurve);
        let ub = geometry::edge_point(&info.b, mid.sb, &fitted.oncurve);
        let ucenter = [(ua[0] + ub[0]) / 2.0, (ua[1] + ub[1]) / 2.0];
        let wu = geometry::certified_winding(ucenter, &up_loops, &up_flats);
        match (wc, wu) {
            (Some(a), Some(b)) if a != 0 && a == b => {}
            _ => {
                v.centers_inked = false;
            }
        }
        let mut peak = 0.0f64;
        for vert in [info.a.i0, info.a.i1, info.b.i0, info.b.i1] {
            let Some(pos) = table.get(vert).copied().flatten() else {
                continue;
            };
            let (cx, cy) = match &candidate[pos] {
                FittedCommand::MoveTo(x, y) | FittedCommand::LineTo(x, y) => (*x as f64, *y as f64),
                FittedCommand::QuadTo(_, _, x, y) | FittedCommand::CurveTo(_, _, _, _, x, y) => {
                    (*x as f64, *y as f64)
                }
                FittedCommand::Close => continue,
            };
            peak = peak.max((cx - fitted.oncurve[vert][0]).hypot(cy - fitted.oncurve[vert][1]));
        }
        info.rounded_peak = Some(peak);
        if !(peak <= info.bound + HEADROOM) {
            v.movement_ok = false;
        }
    }
    if !v.centers_inked {
        v.ok = false;
        v.stage = "center-uninked".to_string();
        return v;
    }
    if !v.movement_ok {
        v.ok = false;
        v.stage = "movement-over-budget".to_string();
        return v;
    }
    v
}

/// Measured post-rounding widths on one command set.
struct Achieved {
    source: f64,
    upstream: f64,
    candidate: f64,
}

fn achieved_widths(prepped: &[PreppedInfo], commands: &[FittedCommand]) -> Vec<Achieved> {
    let cand = geometry::parse_commands(commands)
        .map(|p| p.oncurve)
        .unwrap_or_default();
    prepped
        .iter()
        .map(|info| {
            let mut src = 0.0;
            let mut ups = 0.0;
            let mut got = 0.0;
            for (k, st) in info.stations.iter().enumerate() {
                let qa = geometry::edge_point(&info.a, st.hit.sa, &cand);
                let qb = geometry::edge_point(&info.b, st.hit.sb, &cand);
                got += ((qb[0] - qa[0]) * info.normal[0] + (qb[1] - qa[1]) * info.normal[1]).abs();
                src += info.src_widths[k];
                // Upstream widths reuse the prepare-time measurement, as in
                // the prototype, rather than recomputing the same projection.
                ups += info.fit_widths[k];
            }
            let n = info.stations.len() as f64;
            Achieved {
                source: src / n,
                upstream: ups / n,
                candidate: got / n,
            }
        })
        .collect()
}

fn mean_widths(achieved: &[Achieved]) -> serde_json::Value {
    let n = achieved.len().max(1) as f64;
    serde_json::json!({
        "source": achieved.iter().map(|a| a.source).sum::<f64>() / n,
        "upstream": achieved.iter().map(|a| a.upstream).sum::<f64>() / n,
        "candidate": achieved.iter().map(|a| a.candidate).sum::<f64>() / n,
    })
}

fn achieved_json(prepped: &[PreppedInfo], achieved: &[Achieved]) -> serde_json::Value {
    prepped
        .iter()
        .zip(achieved.iter())
        .map(|(info, a)| {
            serde_json::json!({
                "id": info.id,
                "interval": [info.span_lo, info.span_hi],
                "feet": info.feet,
                "stations": info.stations.iter().map(|st| st.s).collect::<Vec<f64>>(),
                "source_width": a.source,
                "upstream_width": a.upstream,
                "candidate_width": a.candidate,
                "bound": info.bound,
                "prefix": info.prefix,
                "peak": info.peak,
                "rounded_peak": info.rounded_peak,
                "phase_applied": false,
                "grid": null,
            })
        })
        .collect()
}

fn reference_meta(reference: &Reference) -> serde_json::Value {
    serde_json::json!({
        "n_anchors": reference.n_anchors,
        "rel_min": reference.rel_min,
        "rel_max": reference.rel_max,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn anchor(rel: f64) -> Anchor {
        Anchor {
            source_width: 1.0,
            fitted_width: 1.0 + rel,
            rel,
            length: 4.0,
            tangent: [0.0, 1.0],
            source_ids: "r0:c0a(0,0.0000,1.0000)/b(1,0.0000,1.0000)".to_string(),
        }
    }

    #[test]
    fn empty_anchors_fail_closed() {
        let square = vec![
            FittedCommand::MoveTo(0.0, 0.0),
            FittedCommand::LineTo(4.0, 0.0),
            FittedCommand::LineTo(4.0, 4.0),
            FittedCommand::LineTo(0.0, 4.0),
            FittedCommand::Close,
        ];
        let reference = Reference {
            anchors: vec![],
            size_px: 16.0,
            records: 0,
            n_anchors: 0,
            rel_min: None,
            rel_max: None,
            notes: vec![],
        };
        let result = fit(&square, &square, 16.0, &reference, [false, false]).unwrap();
        assert!(!result.applied);
        assert_eq!(result.reason, "no-reference-anchors");
        assert_eq!(result.commands, square);
    }

    #[test]
    fn mismatched_ops_fail_closed() {
        let a = vec![
            FittedCommand::MoveTo(0.0, 0.0),
            FittedCommand::LineTo(4.0, 0.0),
            FittedCommand::Close,
        ];
        let b = vec![
            FittedCommand::MoveTo(0.0, 0.0),
            FittedCommand::LineTo(4.0, 0.0),
            FittedCommand::LineTo(4.0, 4.0),
            FittedCommand::Close,
        ];
        let reference = Reference {
            anchors: vec![anchor(0.0)],
            size_px: 16.0,
            records: 1,
            n_anchors: 1,
            rel_min: Some(0.0),
            rel_max: Some(0.0),
            notes: vec![],
        };
        let result = fit(&a, &b, 16.0, &reference, [false, false]).unwrap();
        assert!(!result.applied);
        assert_eq!(result.reason, "no-correspondence");
        assert_eq!(result.commands, b);
    }

    #[test]
    fn nonpositive_size_is_an_error() {
        let square = vec![FittedCommand::Close];
        let reference = Reference {
            anchors: vec![anchor(0.0)],
            size_px: 16.0,
            records: 1,
            n_anchors: 1,
            rel_min: Some(0.0),
            rel_max: Some(0.0),
            notes: vec![],
        };
        assert!(fit(&square, &square, 0.0, &reference, [false, false]).is_err());
    }

    #[test]
    fn width_weight_matches_published_form() {
        let w = width_weight(1.0, 1.0, [0.0, 1.0], [0.0, 1.0], 16.0);
        assert!((w - 500.0 / 256.0).abs() < 1e-12);
    }

    #[test]
    fn coupling_weight_ignores_run_direction() {
        // Hobby (17) weighs the acute meeting angle: flipping the run
        // spine must not change the coupling, since spine order carries
        // no orientation. Both acute branches are exercised.
        let anchor = [0.0, 1.0];
        let run = [0.7071067811865476, 0.7071067811865476];
        let neg = [-run[0], -run[1]];
        let a = width_weight(1.2, 1.0, acute(run, anchor), anchor, 16.0);
        let b = width_weight(1.2, 1.0, acute(neg, anchor), anchor, 16.0);
        assert_eq!(a, b);
        let cross = [-run[1], run[0]];
        let flipped = [-cross[0], -cross[1]];
        let c = width_weight(1.2, 1.0, acute(cross, anchor), anchor, 16.0);
        let d = width_weight(1.2, 1.0, acute(flipped, anchor), anchor, 16.0);
        assert_eq!(c, d);
    }

    #[test]
    fn svd_solves_rank_deficient_minimum_norm() {
        // Two identical rows: infinite solutions; NumPy lstsq returns the
        // minimum-norm one (0.5 each for x1 + x2 = 1).
        let a = nalgebra::DMatrix::from_row_slice(2, 2, &[1.0, 1.0, 1.0, 1.0]);
        let b = nalgebra::DVector::from_vec(vec![1.0, 1.0]);
        let x = min_norm_solve(&a, &b);
        assert!((x[0] - 0.5).abs() < 1e-12);
        assert!((x[1] - 0.5).abs() < 1e-12);
    }

    #[test]
    fn svd_keeps_small_rank_rule() {
        // Single tiny-but-nonzero singular value above the NumPy cutoff.
        let a = nalgebra::DMatrix::from_row_slice(2, 2, &[1.0, 0.0, 0.0, 1e-10]);
        let b = nalgebra::DVector::from_vec(vec![1.0, 1e-10]);
        let x = min_norm_solve(&a, &b);
        assert!((x[0] - 1.0).abs() < 1e-9);
        assert!((x[1] - 1.0).abs() < 1e-6);
    }

    #[test]
    fn width_weight_asymmetric_scaled_tangents() {
        let w = width_weight(1.7, 1.0, [3.0, 4.0], [-1.0, 7.0], 10.0);
        assert!((w - 1.8254425977371571).abs() < 1e-12);
    }

    #[test]
    fn acute_keeps_or_flips_orientation_by_sign() {
        assert_eq!(acute([3.0, 4.0], [-4.0, 3.0]), [3.0, 4.0]);
        assert_eq!(acute([3.0, 4.0], [-3.0, -4.0]), [-3.0, -4.0]);
        assert_eq!(acute([1.0, -2.0], [3.0, 1.0]), [1.0, -2.0]);
        assert_eq!(acute([-2.0, 1.0], [1.0, 3.0]), [-2.0, 1.0]);
    }
    #[test]
    fn affine_samples_preserve_endpoint_and_interior_coordinates() {
        let points = [[-4.0, 8.0], [12.0, -8.0]];
        assert_eq!(Sample::vertex(1).point(&points), points[1]);
        assert_eq!(Sample::affine(0, 0.25, 1, 0.75).point(&points), [8.0, -4.0]);
    }
}
//! Terminal reference-height constraints inside the width solve.
//!
//! Source: Hersch sections 5-6 (reference-line phase with diagonal-width
//! control) and Hobby 3.3 (common displacement of horizontal regions).
//! Project adaptation: a nonzero horizontal straight source edge whose
//! endpoints also share one upstream height pins both Y coordinates to that
//! height while X joins the source-relative width solve. Source control-box
//! planes classify diagnostics; another stroke extending beyond an edge
//! cannot release its local reference phase. Upright source
//! verticals keep their upstream X while Y stays free. Explicit closing
//! endpoints alias one shared unknown (Hobby 6). Invariant: removal-free
//! correction only; unsupported geometry, budget overrun, movement or
//! validity failure all return the upstream outline unchanged.

use super::{
    abstain, curves, geometry, geometry::Parsed, FitResult, Reference, RowGroup, HEADROOM,
    MAX_COMMANDS,
};
use crate::probe::FittedCommand;
use nalgebra::{DMatrix, DVector};
use std::collections::{BTreeMap, HashMap, HashSet};

/// Unrounded raw source command in f64, pre-scaled to pixels.
///
/// The parent owns raw capture integration (units, scaling); this type only
/// carries the already-scaled geometry [`parse_raw`] folds into [`Parsed`].
#[derive(Clone, Copy, Debug)]
pub enum RawCommand {
    MoveTo([f64; 2]),
    LineTo([f64; 2]),
    QuadTo([f64; 2], [f64; 2]),
    CurveTo([f64; 2], [f64; 2], [f64; 2]),
    Close,
}

/// Reference edge location relative to the raw control box.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Plane {
    Min,
    Max,
    Interior,
}

impl Plane {
    fn as_str(self) -> &'static str {
        match self {
            Plane::Min => "min",
            Plane::Max => "max",
            Plane::Interior => "interior",
        }
    }
}

/// Source-horizontal reference edge with one retained upstream height.
#[derive(Clone, Debug)]
pub struct Cap {
    pub vertices: (usize, usize),
    pub plane: Plane,
    pub source_y: f64,
    pub upstream_y: f64,
}

/// Vertical straight source edge sharing one upstream X.
#[derive(Clone, Debug)]
pub struct Upright {
    pub vertices: (usize, usize),
    pub source_x: f64,
    pub upstream_x: f64,
}

/// Fold unrounded raw commands into contours, mirroring
/// [`geometry::parse_commands`] without f32 rounding.
pub fn parse_raw(commands: &[RawCommand]) -> Result<Parsed, ()> {
    let mut oncurve: Vec<[f64; 2]> = Vec::new();
    let mut offcurve: Vec<[f64; 2]> = Vec::new();
    let mut contours: Vec<Vec<geometry::Segment>> = Vec::new();
    let mut current: Vec<geometry::Segment> = Vec::new();
    let mut pen: Option<usize> = None;
    let mut start: Option<usize> = None;
    let finite = |p: [f64; 2]| {
        if p[0].is_finite() && p[1].is_finite() {
            Some(p)
        } else {
            None
        }
    };
    for cmd in commands {
        match *cmd {
            RawCommand::MoveTo(p) => {
                if !current.is_empty() {
                    contours.push(std::mem::take(&mut current));
                }
                let Some(pt) = finite(p) else {
                    return Err(());
                };
                oncurve.push(pt);
                pen = Some(oncurve.len() - 1);
                start = pen;
            }
            RawCommand::LineTo(p) => {
                let (Some(pt), Some(prev)) = (finite(p), pen) else {
                    return Err(());
                };
                oncurve.push(pt);
                let next = oncurve.len() - 1;
                current.push(geometry::Segment::Line { a: prev, b: next });
                pen = Some(next);
            }
            RawCommand::QuadTo(c, p) => {
                let (Some(cc), Some(pt), Some(prev)) = (finite(c), finite(p), pen) else {
                    return Err(());
                };
                offcurve.push(cc);
                let ci = offcurve.len() - 1;
                oncurve.push(pt);
                let next = oncurve.len() - 1;
                current.push(geometry::Segment::Quad {
                    c: ci,
                    a: prev,
                    b: next,
                });
                pen = Some(next);
            }
            RawCommand::CurveTo(c1, c2, p) => {
                let (Some(cc1), Some(cc2), Some(pt), Some(prev)) =
                    (finite(c1), finite(c2), finite(p), pen)
                else {
                    return Err(());
                };
                offcurve.push(cc1);
                let i1 = offcurve.len() - 1;
                offcurve.push(cc2);
                let i2 = offcurve.len() - 1;
                oncurve.push(pt);
                let next = oncurve.len() - 1;
                current.push(geometry::Segment::Cubic {
                    c1: i1,
                    c2: i2,
                    a: prev,
                    b: next,
                });
                pen = Some(next);
            }
            RawCommand::Close => {
                if let (Some(p), Some(s)) = (pen, start) {
                    if p != s {
                        current.push(geometry::Segment::Line { a: p, b: s });
                    }
                }
                if !current.is_empty() {
                    contours.push(std::mem::take(&mut current));
                }
                pen = None;
                start = None;
            }
        }
    }
    if !current.is_empty() {
        contours.push(current);
    }
    Ok(Parsed {
        oncurve,
        offcurve,
        contours,
    })
}

/// Flat source reference edges, including stroke ends below an ascender.
///
/// An empty outline is a valid font glyph and carries no caps. Only nonzero
/// exactly horizontal straight source segments whose endpoints also share
/// one upstream Y qualify. Hobby section 3.3 fits horizontal regions locally;
/// Hersch sections 5-6 preserve their grid phase while controlling diagonal
/// width. The height belongs to the existing fit, never a new rounded target.
/// Global control-box planes classify diagnostics, not eligibility: a
/// different stroke extending higher cannot release this reference edge.
pub fn detect_caps(raw: &Parsed, upstream: &Parsed) -> (Vec<Cap>, Option<f64>, Option<f64>) {
    let mut ys = raw.oncurve.iter().chain(raw.offcurve.iter()).map(|p| p[1]);
    let Some(first) = ys.next() else {
        return (Vec::new(), None, None);
    };
    let mut lo = first;
    let mut hi = first;
    for y in ys {
        lo = lo.min(y);
        hi = hi.max(y);
    }
    let up = &upstream.oncurve;
    let mut caps = Vec::new();
    let mut seen = HashSet::new();
    for contour in &raw.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i0, i1) = seg.endpoints();
            let (Some(a), Some(b)) = (raw.oncurve.get(i0), raw.oncurve.get(i1)) else {
                continue;
            };
            if a[0] == b[0] || a[1] != b[1] {
                continue;
            }
            let (Some(ua), Some(ub)) = (up.get(i0), up.get(i1)) else {
                continue;
            };
            if ua[1] != ub[1] {
                continue;
            }
            if !seen.insert((i0, i1, a[1].to_bits())) {
                continue;
            }
            caps.push(Cap {
                vertices: (i0, i1),
                plane: if a[1] == lo {
                    Plane::Min
                } else if a[1] == hi {
                    Plane::Max
                } else {
                    Plane::Interior
                },
                source_y: a[1],
                upstream_y: ua[1],
            });
        }
    }
    (caps, Some(lo), Some(hi))
}

/// Nonzero vertical straight source edges with shared upstream X.
pub fn detect_uprights(raw: &Parsed, upstream: &Parsed) -> Vec<Upright> {
    let up = &upstream.oncurve;
    let mut found = Vec::new();
    let mut seen = HashSet::new();
    for contour in &raw.contours {
        for seg in contour {
            if !seg.is_line() {
                continue;
            }
            let (i0, i1) = seg.endpoints();
            let (Some(a), Some(b)) = (raw.oncurve.get(i0), raw.oncurve.get(i1)) else {
                continue;
            };
            if a[1] == b[1] || a[0] != b[0] {
                continue;
            }
            let (Some(ua), Some(ub)) = (up.get(i0), up.get(i1)) else {
                continue;
            };
            if ua[0] != ub[0] {
                continue;
            }
            if !seen.insert((i0, i1)) {
                continue;
            }
            found.push(Upright {
                vertices: (i0, i1),
                source_x: a[0],
                upstream_x: ua[0],
            });
        }
    }
    found
}

/// Contour/segment shape agreement between two parsed outlines.
fn same_shape(a: &Parsed, b: &Parsed) -> bool {
    if a.contours.len() != b.contours.len() || a.oncurve.len() != b.oncurve.len() {
        return false;
    }
    let op = |s: &geometry::Segment| match s {
        geometry::Segment::Line { .. } => 0,
        geometry::Segment::Quad { .. } => 1,
        geometry::Segment::Cubic { .. } => 2,
    };
    a.contours.iter().zip(b.contours.iter()).all(|(ca, cb)| {
        ca.len() == cb.len() && ca.iter().zip(cb.iter()).all(|(x, y)| op(x) == op(y))
    })
}

/// Explicit closing-endpoint aliases for line/quad/cubic contours.
///
/// `parse_commands` materializes a closing line when the last endpoint index
/// differs from the contour start; when that edge ends at duplicate contour
/// start coordinates its start vertex is an encoding artifact, not separate
/// geometry.
fn closure_aliases(parsed: &Parsed) -> BTreeMap<usize, usize> {
    let mut weld = BTreeMap::new();
    for contour in &parsed.contours {
        if contour.is_empty() {
            continue;
        }
        let (Some(first), Some(last)) = (contour.first(), contour.last()) else {
            continue;
        };
        if !last.is_line() {
            continue;
        }
        let (canon, _) = first.endpoints();
        let (dup, end) = last.endpoints();
        if end != canon || dup == canon {
            continue;
        }
        let (Some(pd), Some(pc)) = (parsed.oncurve.get(dup), parsed.oncurve.get(canon)) else {
            continue;
        };
        if *pd != *pc {
            continue;
        }
        weld.insert(dup, canon);
    }
    weld
}

/// Duplicate-canonical equality rows; unresolved ownership abstains.
///
/// An explicit closing endpoint alias is an encoding artifact, not separate
/// geometry; Hobby 6 carries shared vertices as one unknown, so each alias
/// pair is equated in the source-displacement frame. Only an alias that is
/// itself variable, with a non-variable canonical and no fixed axis of its
/// own, merges into the emission set; any other variable contact abstains
/// rather than splitting the point.
fn weld_constraints(
    weld: &BTreeMap<usize, usize>,
    var_verts: &HashSet<usize>,
    fixed: &HashMap<(usize, usize), f64>,
    base: &[[f64; 2]],
) -> (Vec<(Vec<f64>, f64)>, HashSet<usize>, Option<(usize, usize)>) {
    let mut rows = Vec::new();
    let mut merged = HashSet::new();
    for (&dup, &canon) in weld {
        if !var_verts.contains(&dup) && !var_verts.contains(&canon) {
            continue;
        }
        if var_verts.contains(&canon)
            || !var_verts.contains(&dup)
            || fixed.contains_key(&(dup, 0))
            || fixed.contains_key(&(dup, 1))
        {
            return (Vec::new(), HashSet::new(), Some((dup, canon)));
        }
        for axis in 0..2 {
            let mut row = vec![0.0; 2 * base.len()];
            row[2 * dup + axis] = 1.0;
            row[2 * canon + axis] = -1.0;
            rows.push((row, base[canon][axis] - base[dup][axis]));
        }
        merged.insert(dup);
    }
    (rows, merged, None)
}

/// Finite shape values for the (17) coupling; content outside this is a
/// caller error, never a solved guess.
fn valid_anchors(anchors: &[super::Anchor]) -> bool {
    anchors.iter().all(|a| {
        a.source_width.is_finite()
            && a.source_width > 0.0
            && a.rel.is_finite()
            && a.length.is_finite()
            && a.length > 0.0
            && a.tangent[0].is_finite()
            && a.tangent[1].is_finite()
            && (a.tangent[0] != 0.0 || a.tangent[1] != 0.0)
    })
}

/// Per-coordinate fixed-column elimination, matching the parent solve form.
fn eliminate_plain(
    rows: &[Vec<f64>],
    consts: &[f64],
    fixed: &HashMap<(usize, usize), f64>,
    nvars: usize,
) -> (Vec<Vec<f64>>, Vec<f64>, Vec<usize>) {
    let mut free = Vec::new();
    for v in 0..nvars {
        for c in 0..2 {
            if !fixed.contains_key(&(v, c)) {
                free.push(2 * v + c);
            }
        }
    }
    // Deterministic accumulation order: HashMap iteration is random, and
    // float addition is not associative.
    let mut keys: Vec<(usize, usize)> = fixed.keys().copied().collect();
    keys.sort();
    let mut matrix = Vec::with_capacity(rows.len());
    let mut out = Vec::with_capacity(rows.len());
    for (row, constant) in rows.iter().zip(consts.iter()) {
        let mut adjusted = *constant;
        for &(v, c) in &keys {
            adjusted += row[2 * v + c] * fixed[&(v, c)];
        }
        matrix.push(row.clone());
        out.push(adjusted);
    }
    (matrix, out, free)
}

fn inf_norm(v: &DVector<f64>) -> f64 {
    v.iter().fold(0.0_f64, |m, x| m.max(x.abs()))
}

/// Exact hard rows via SVD particular plus nullspace least squares.
///
/// The particular solution carries the hard constraints; source shape and
/// (17) coupling run in the nullspace. Rank follows the NumPy singular-value
/// convention; a hard residual outside the relative band means inconsistent
/// constraints, never a guess. Without hard rows this is plain minimum-norm
/// least squares.
fn solve_hard(
    soft: &[(RowGroup, Vec<f64>, f64)],
    hard: &[(Vec<f64>, f64)],
    fixed: &HashMap<(usize, usize), f64>,
    nvars: usize,
) -> Option<Vec<f64>> {
    if hard.is_empty() {
        return Some(super::solve_constrained(soft, fixed, nvars));
    }
    let soft_rows: Vec<Vec<f64>> = soft.iter().map(|(_, r, _)| r.clone()).collect();
    let soft_c: Vec<f64> = soft.iter().map(|(_, _, c)| *c).collect();
    let hard_rows: Vec<Vec<f64>> = hard.iter().map(|(r, _)| r.clone()).collect();
    let hard_c: Vec<f64> = hard.iter().map(|(_, c)| *c).collect();
    let (soft_m, soft_const, free) = eliminate_plain(&soft_rows, &soft_c, fixed, nvars);
    let (hard_m, hard_const, _) = eliminate_plain(&hard_rows, &hard_c, fixed, nvars);
    let mut loose = vec![0.0; 2 * nvars];
    for (&(v, axis), &value) in fixed {
        loose[2 * v + axis] = value;
    }
    let (k, n) = (hard_m.len(), free.len());
    let mut flat = Vec::with_capacity(k * n);
    for row in &hard_m {
        for &col in &free {
            flat.push(row[col]);
        }
    }
    let mat = DMatrix::from_row_slice(k, n, &flat);
    let rhs = DVector::from_vec(hard_const.iter().map(|c| -c).collect());
    if n == 0 {
        if inf_norm(&rhs) > 1e-9 * inf_norm(&rhs).max(1.0) {
            return None;
        }
        return Some(loose);
    }
    // Zero rows preserve the hard equations while making the thin native
    // factorization retain the complete right singular basis, as NumPy's
    // full_matrices=True does for an underdetermined system.
    let padded = DMatrix::from_fn(k.max(n), n, |i, j| if i < k { mat[(i, j)] } else { 0.0 });
    let padded_rhs = DVector::from_iterator(
        k.max(n),
        (0..k.max(n)).map(|i| if i < k { rhs[i] } else { 0.0 }),
    );
    let svd = padded.svd(true, true);
    let sigma_max = svd.singular_values.iter().cloned().fold(0.0_f64, f64::max);
    let tol = f64::EPSILON * (k.max(n) as f64) * sigma_max;
    let rank = if sigma_max > 0.0 {
        svd.singular_values.iter().filter(|&&s| s > tol).count()
    } else {
        0
    };
    let (Some(u), Some(vt)) = (svd.u, svd.v_t) else {
        return None;
    };
    let utb: DVector<f64> = u.transpose() * &padded_rhs;
    let mut particular = DVector::zeros(n);
    for (i, &s) in svd
        .singular_values
        .iter()
        .enumerate()
        .filter(|(_, s)| **s > tol)
    {
        let c = utb[i] / s;
        for j in 0..n {
            particular[j] += vt[(i, j)] * c;
        }
    }
    let resid = inf_norm(&(mat.clone() * &particular - &rhs));
    if resid > 1e-9 * inf_norm(&rhs).max(1.0) {
        return None;
    }
    let null_dim = n - rank;
    if null_dim == 0 {
        for (t, &col) in free.iter().enumerate() {
            loose[col] = particular[t];
        }
        return Some(loose);
    }
    let mut null_basis = DMatrix::zeros(n, null_dim);
    for (t, (i, _)) in svd
        .singular_values
        .iter()
        .enumerate()
        .filter(|(_, s)| **s <= tol)
        .enumerate()
    {
        for j in 0..n {
            null_basis[(j, t)] = vt[(i, j)];
        }
    }
    let mut a_flat = Vec::with_capacity(soft_m.len() * null_dim);
    for row in &soft_m {
        for t in 0..null_dim {
            let mut dot = 0.0;
            for (k2, &col) in free.iter().enumerate() {
                dot += row[col] * null_basis[(k2, t)];
            }
            a_flat.push(dot);
        }
    }
    let a2 = DMatrix::from_row_slice(soft_m.len(), null_dim, &a_flat);
    let mut want_data = Vec::with_capacity(soft_m.len());
    for (m, row) in soft_m.iter().enumerate() {
        let mut dot = 0.0;
        for (t, &col) in free.iter().enumerate() {
            dot += row[col] * particular[t];
        }
        want_data.push(-soft_const[m] - dot);
    }
    let want = DVector::from_vec(want_data);
    let alpha = super::min_norm_solve(&a2, &want);
    let correction = &null_basis * &alpha;
    for (t, &col) in free.iter().enumerate() {
        loose[col] = particular[t] + correction[t];
    }
    Some(loose)
}

fn caps_json(caps: &[Cap]) -> serde_json::Value {
    caps.iter()
        .map(|c| {
            serde_json::json!({
                "vertices": [c.vertices.0, c.vertices.1],
                "plane": c.plane.as_str(),
                "source_y": c.source_y,
                "upstream_y": c.upstream_y,
            })
        })
        .collect()
}

fn uprights_json(found: &[Upright]) -> serde_json::Value {
