        })
        .sum();
    let flat_base_cand: Vec<f64> = cand
        .oncurve
        .iter()
        .zip(base.iter())
        .flat_map(|(c, b)| [c[0] - b[0], c[1] - b[1]])
        .collect();
    let cost_candidate: f64 = match_rows
        .iter()
        .map(|(row, constant)| {
            let dot: f64 = row
                .iter()
                .zip(flat_base_cand.iter())
