    feet: serde_json::Value,
}

fn acute(tangent: [f64; 2], other: [f64; 2]) -> [f64; 2] {
    if tangent[0] * other[0] + tangent[1] * other[1] < 0.0 {
        [-tangent[0], -tangent[1]]
    } else {
        tangent
    }
}

