pub(super) fn parity_target(axis: f64, width: f64) -> Option<f64> {
    let n = (width + 0.5).floor() as i64;
    if n < 1 {
        return None;
    }
    if n % 2 == 1 {
        let base = (axis - 0.5).floor() + 0.5;
