            std::mem::swap(&mut second.i0, &mut second.i1);
            let (t0, t1) = (second.t0, second.t1);
            second.t0 = 1.0 - t1;
            second.t1 = 1.0 - t0;
        }
        matches.push((s.clone(), second, dist));
